@Slf4j
@PluginDescriptor(
        name = "BingoScape",
        description = "Participate in bingo events with your clan or friends",
        tags = {"bingo", "clan", "event", "minigame"}
)
public class BingoScapePlugin extends Plugin {
    // Constants
    private static final String ICON_PATH = "/sidepanel_icon.png";
    private static final String PNG_FORMAT = "png";
    private static final MediaType MEDIA_TYPE_PNG = MediaType.parse("image/png");

    // Injected components
    @Inject
    private Client client;

    @Inject
    private ClientUI clientUI;

    @Inject
    private ClientThread clientThread;

    @Getter
    @Inject
    private BingoScapeConfig config;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OkHttpClient httpClient;

    @Inject
    private DrawManager drawManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private BingoCodephraseOverlay codephraseOverlay;

    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private Gson gson;

    @Inject
    private BingoScapeApiService apiService;

    @Inject
    private TileRequirementMatcher requirementMatcher;

    @Inject
    private AutoSubmissionHandler autoSubmissionHandler;

    @Inject
    private org.bingoscape.services.TeamDropPoller teamDropPoller;

    @Inject
    private org.bingoscape.notifications.DropNotificationOverlay dropOverlay;

    @Getter
    @Inject
    private net.runelite.client.game.ItemManager itemManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private KeyManager keyManager;

    @Inject
    private BingoBoardOverlay boardOverlay;

    @Inject
    private BoardInputListener boardInputListener;

    @Inject
    private BoardState boardState;

    @Inject
    private TileImageCache tileImageCache;

    // Plugin components
    private NavigationButton navButton;
    private BingoScapePanel panel;
    private JDialog screenshotPreviewDialog;

    private final HotkeyListener boardHotkeyListener = new HotkeyListener(() -> config.boardToggleHotkey()) {
        @Override
        public void hotkeyPressed() {
            toggleBoard();
        }
    };

    // State (written from HTTP callback threads, read by overlays on the client thread)
    private final List<EventData> activeEvents = new CopyOnWriteArrayList<>();
    @Getter
    private volatile EventData currentEvent;
    @Getter
    private volatile Bingo currentBingo;
    private boolean isLoggedIn;
    // Event, bingo and team the team drop feed is baselined for
    private volatile String teamDropScope = "";

    @Override
    protected void startUp() {
        // Load the icon for the side panel
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), ICON_PATH);

        // Create and initialize the side panel
        panel = new BingoScapePanel(this);
        navButton = NavigationButton.builder()
                .tooltip("BingoScape")
                .icon(icon)
                .priority(5)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
        overlayManager.add(codephraseOverlay);
        overlayManager.add(boardOverlay);
        overlayManager.add(dropOverlay);
        mouseManager.registerMouseListener(boardInputListener);
        mouseManager.registerMouseWheelListener(boardInputListener);
        keyManager.registerKeyListener(boardInputListener);
        keyManager.registerKeyListener(boardHotkeyListener);

        teamDropPoller.configureBoardRefresh(
                () -> currentBingo == null || currentBingo.getId() == null ? null : currentBingo.getId().toString(),
                this::refreshBingoBoard);
        updateTeamDropPolling(false);

        // Load all events and handle pinned bingo
        if (hasApiKey()) {
            String pinnedBingoId = config.pinnedBingoId();
            apiService.fetchEvents(
                events -> {
                    activeEvents.clear();
                    activeEvents.addAll(events);
                    sortEvents(activeEvents);
                    panel.updateEventsList(activeEvents);

                    // If there's a pinned bingo, find and select its event
                    if (!pinnedBingoId.isEmpty()) {
                        UUID pinnedId = UUID.fromString(pinnedBingoId);
                        for (EventData event : events) {
                            if (event.getBingos().stream().anyMatch(b -> b.getId().equals(pinnedId))) {
                                // Found the event with pinned bingo, select it and load the bingo
                                setEventDetails(event);
                                apiService.refreshBingoBoard(
                                    pinnedId,
                                    bingo -> selectBingo(bingo),
                                    error -> log.error("Failed to load pinned bingo: " + error)
                                );
                                break;
                            }
                        }
                    }
                },
                error -> log.error("Failed to load events: " + error)
            );
        }
    }

    @Override
    protected void shutDown() {
        teamDropPoller.stop();
        dropOverlay.clear();
        overlayManager.remove(dropOverlay);
        clientToolbar.removeNavigation(navButton);
        overlayManager.remove(codephraseOverlay);
        overlayManager.remove(boardOverlay);
        mouseManager.unregisterMouseListener(boardInputListener);
        mouseManager.unregisterMouseWheelListener(boardInputListener);
        keyManager.unregisterKeyListener(boardInputListener);
        keyManager.unregisterKeyListener(boardHotkeyListener);
        boardState.hide();
        boardState.resetCaptures();
        tileImageCache.clear();

        BingoScapePanel closingPanel = panel;
        JDialog closingDialog = screenshotPreviewDialog;
        screenshotPreviewDialog = null;
        SwingUtilities.invokeLater(() -> {
            closingPanel.shutdown();
            if (closingDialog != null) {
                closingDialog.dispose();
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!BingoScapeConfig.CONFIG_GROUP.equals(event.getGroup())) {
            return;
        }

        switch (event.getKey()) {
            case "apiKey":
                updateTeamDropPolling(true);
                return;
            case "showToastNotifications":
            case "showTeamDropNotifications":
            case "showTileCompletedNotifications":
                updateTeamDropPolling(false);
                return;
            default:
                break;
        }
        if (!"boardDisplayMode".equals(event.getKey())) {
            return;
        }

        // Close whichever board view no longer matches the selected mode
        if (config.boardDisplayMode() == BoardDisplayMode.WINDOW) {
            hideBoard();
        } else {
            SwingUtilities.invokeLater(panel::disposeBoardWindow);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        switch (gameStateChanged.getGameState()) {
            case HOPPING:
            case LOGGING_IN:
            case LOGIN_SCREEN:
            case LOGIN_SCREEN_AUTHENTICATOR:
            case CONNECTION_LOST:
                dropOverlay.clear();
                break;
            default:
                break;
        }

        switch (gameStateChanged.getGameState()) {
            case LOGGED_IN:
                updateTeamDropPolling(false);
                break;
            case LOGIN_SCREEN:
            case CONNECTION_LOST:
                teamDropPoller.stop();
                break;
            default:
                break;
        }

        // Only update login state if transitioning to LOGGED_IN from a non-logged-in state
        if (gameStateChanged.getGameState() == GameState.LOGGED_IN && !isLoggedIn) {
            isLoggedIn = true;
            if (hasApiKey()) {
                fetchActiveEvents();
            }
        } else if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN) {
            isLoggedIn = false;
        }
    }

    public void fetchActiveEvents() {
        if (!hasApiKey()) {
            return;
        }

        apiService.fetchActiveEvents(
            events -> {
                activeEvents.clear();
                activeEvents.addAll(events);
                sortEvents(activeEvents);
                panel.updateEventsList(activeEvents);
            },
            error -> showErrorMessage(error.getMessage())
        );
    }

    private void sortEvents(List<EventData> events) {
        Date now = new Date();

        // Filter events based on configuration
        events.removeIf(event -> {
            // Filter past events
            if (config.hidePastEvents() && event.getEndDate().before(now)) {
                return true;
            }

            // Filter locked events
            if (config.hideLockedEvents() && event.isLocked()) {
                return true;
            }

            // Filter upcoming events
            if (config.hideUpcomingEvents() && event.getStartDate().after(now)) {
                return true;
            }

            return false;
        });

        // Sort remaining events
        events.sort((e1, e2) -> {
            // First sort by locked status (active events first)
            if (e1.isLocked() != e2.isLocked()) {
                return e1.isLocked() ? 1 : -1;
            }

            // Then sort by start date (upcoming events first)
            boolean e1Upcoming = e1.getStartDate().after(now);
            boolean e2Upcoming = e2.getStartDate().after(now);

            if (e1Upcoming != e2Upcoming) {
                return e1Upcoming ? -1 : 1;
            }

            // For events with the same status, sort by start date (most recent first)
            int dateComparison = e2.getStartDate().compareTo(e1.getStartDate());
            if (dateComparison != 0) {
                return dateComparison;
            }

            // Finally, sort alphabetically by title
            return e1.getTitle().compareToIgnoreCase(e2.getTitle());
        });
    }

    public void setEventDetails(EventData eventData) {
        currentEvent = eventData;
        panel.updateEventDetails(eventData);

        Bingo bingo = pickBingo(eventData);
        if (bingo != null) {
            selectBingo(bingo);
        }
        rebaselineTeamDropsIfScopeChanged();
    }

    /**
     * Starts or stops the team drop feed for the current game state and config.
     *
     * @param apiKeyChanged forget an earlier 401/403 and start from a fresh baseline
     */
    private void updateTeamDropPolling(boolean apiKeyChanged) {
        if (client.getGameState() != GameState.LOGGED_IN) {
            teamDropPoller.stop();
        } else if (apiKeyChanged) {
            teamDropPoller.restart();
        } else if (teamDropPoller.isEnabled()) {
            teamDropPoller.start(this::getAccountName);
        } else {
            teamDropPoller.stop();
        }
    }

    private void rebaselineTeamDropsIfScopeChanged() {
        EventData event = currentEvent;
        Bingo bingo = currentBingo;
        String scope = (event == null ? "" : event.getId() + "/" + (event.getUserTeam() == null ? "" : event.getUserTeam().getName()))
                + "|" + (bingo == null ? "" : bingo.getId());
        if (!scope.equals(teamDropScope)) {
            teamDropScope = scope;
            teamDropPoller.rebaseline();
        }
    }

    /**
     * The bingo to show for an event: the pinned one, else the current one if it belongs to the event,
     * else the first. The panel uses the same rule, so both agree regardless of which thread runs first.
     */
    public Bingo pickBingo(EventData eventData) {
        List<Bingo> bingos = eventData.getBingos() == null ? List.of() : new ArrayList<>(eventData.getBingos());
        if (bingos.isEmpty()) {
            return null;
        }

        String pinnedId = config.pinnedBingoId();
        Bingo current = currentBingo;
        for (Bingo bingo : bingos) {
            if (bingo.getId().toString().equals(pinnedId)) {
                return bingo;
            }
        }
        if (current != null) {
            for (Bingo bingo : bingos) {
                if (bingo.getId().equals(current.getId())) {
                    return bingo;
                }
            }
        }
        return bingos.get(0);
    }

    public void selectBingo(Bingo bingo) {
        currentBingo = bingo;
        panel.displayBingoBoard(currentBingo);
        rebaselineTeamDropsIfScopeChanged();

        // Rebuild requirement matcher lookup maps for auto-submission
        // The matcher will query currentBingo directly from the plugin
        requirementMatcher.rebuildLookupMaps();

        if (bingo != null) {
            log.info("Selected bingo '{}' - Auto-submission ready. {}", bingo.getTitle(), requirementMatcher.getStats());
        } else {
            log.info("Cleared bingo selection - Auto-submission disabled");
        }
    }

    public void takeScreenshot(UUID tileId, Consumer<byte[]> callback) {
        // Unlike the old window, the board overlay is drawn into the game frame; keep it out of the capture.
        // The frame listener is registered from the client thread so it fires for a frame drawn after
        // the suppression flag is set.
        // A counter rather than a flag, so overlapping captures (auto + manual) all exclude the board.
        boardState.beginCapture();
        clientThread.invokeLater(() -> drawManager.requestNextFrameListener(image -> {
            boardState.endCapture();
            executor.submit(() -> {
                try {
                    BufferedImage screenshot = convertToBufferedImage(image);
                    byte[] screenshotBytes = convertImageToBytes(screenshot);
                    callback.accept(screenshotBytes);
                } catch (IOException e) {
                    log.error("Failed to process screenshot", e);
                    showErrorMessage("Failed to take screenshot for submission.");
                    callback.accept(null);
                }
            });
        }));
    }

    /**
     * Manual submission from the board overlay: capture, let the user confirm in a preview dialog, then submit.
     */
    public void captureAndPreviewSubmission(Tile tile) {
        takeScreenshot(tile.getId(), screenshotBytes -> SwingUtilities.invokeLater(() -> {
            // takeScreenshot already reported the failure in chat
            if (screenshotBytes == null) {
                return;
            }

            if (screenshotPreviewDialog != null) {
                screenshotPreviewDialog.dispose();
            }
            screenshotPreviewDialog = ScreenshotPreviewDialog.create(
                    SwingUtilities.getWindowAncestor(client.getCanvas()),
                    tile,
                    screenshotBytes,
                    bytes -> submitTileCompletionWithScreenshot(tile.getId(), bytes));
            screenshotPreviewDialog.setVisible(true);
        }));
    }

    private BufferedImage convertToBufferedImage(Image image) {
        BufferedImage screenshot = new BufferedImage(
                image.getWidth(null),
                image.getHeight(null),
                BufferedImage.TYPE_INT_ARGB
        );
        Graphics graphics = screenshot.getGraphics();
        graphics.drawImage(image, 0, 0, null);
        graphics.dispose();
        return screenshot;
    }

    private byte[] convertImageToBytes(BufferedImage image) throws IOException {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        ImageIO.write(image, PNG_FORMAT, outputStream);
        return outputStream.toByteArray();
    }

    public void submitTileCompletionWithScreenshot(UUID tileId, byte[] screenshotBytes) {
        apiService.submitTileCompletion(
            tileId,
            screenshotBytes,
            updatedBingo -> {
                showSuccessMessage("Tile submission sent to BingoScape!");
                updateCurrentBingoAndPanel(updatedBingo);
            },
            error -> {
                showErrorMessage(error.getMessage());
                if (error.isLocked()) {
                    // Our copy of the bingo is stale; reload so the board shows it as locked
                    refreshBingoBoard();
                }
            }
        );
    }

    /**
     * Submits a tile completion automatically with metadata.
     * Used by the auto-submission handler to include context about the drop.
     */
    public void submitTileAutomaticWithMetadata(UUID tileId, byte[] screenshotBytes, AutoSubmissionMetadata metadata) {
        apiService.submitTileAutomatic(
            tileId,
            screenshotBytes,
            metadata,
            updatedBingo -> {
                log.info("Auto-submission successful for tile {}", tileId);
                updateCurrentBingoAndPanel(updatedBingo);
            },
            error -> {
                log.error("Auto-submission failed (HTTP {}): {}", error.getStatusCode(), error.getMessage());
                if (error.isLocked()) {
                    // Reloading marks the bingo locked locally, which stops further auto-submission attempts
                    refreshBingoBoard();
                }
            }
        );
    }

    public void refreshBingoBoard() {
        refreshBingoBoard(null);
    }

    /**
     * Reloads the current bingo; {@code onDone} runs after success or failure (on an HTTP callback thread).
     */
    public void refreshBingoBoard(Runnable onDone) {
        if (currentBingo == null || !hasApiKey()) {
            if (onDone != null) {
                onDone.run();
            }
            return;
        }

        apiService.refreshBingoBoard(
            currentBingo.getId(),
            bingo -> {
                updateCurrentBingoAndPanel(bingo);
                if (onDone != null) {
                    onDone.run();
                }
            },
            error -> {
                log.error("Failed to refresh bingo board (HTTP {}): {}", error.getStatusCode(), error.getMessage());
                if (onDone != null) {
                    onDone.run();
                }
            }
        );
    }

    public boolean isBoardVisible() {
        return boardState.isVisible();
    }

    public void toggleBoard() {
        if (config.boardDisplayMode() == BoardDisplayMode.OVERLAY && boardState.isVisible()) {
            hideBoard();
        } else {
            showBoard();
        }
    }

    public void showBoard() {
        Bingo bingo = currentBingo;
        if (bingo == null) {
            showErrorMessage("Select a bingo board first.");
            return;
        }

        if (config.boardDisplayMode() == BoardDisplayMode.WINDOW) {
            panel.openBoardWindow(bingo);
            return;
        }

        boardState.show();
        panel.setBoardButtonState(true);
    }

    public void hideBoard() {
        boardState.hide();
        panel.setBoardButtonState(false);
    }

    public void reloadBoard() {
        boardState.startReload();
        refreshBingoBoard(boardState::finishReload);
    }

    public void toggleBoardPin() {
        Bingo bingo = currentBingo;
        if (bingo == null) {
            return;
        }

        if (bingo.getId().toString().equals(config.pinnedBingoId())) {
            unpinBingo();
        } else {
            pinBingo(bingo.getId());
        }
        panel.refreshPinState();
    }

    private void updateCurrentBingoAndPanel(Bingo updatedBingo) {
        for(EventData e : activeEvents) {
            // Swap in a new list instead of mutating: the panel iterates these lists on the EDT
            List<Bingo> bingos = new ArrayList<>(e.getBingos());
            bingos.replaceAll(b -> b.getId().equals(updatedBingo.getId()) ? updatedBingo : b);
            e.setBingos(bingos);
        }
        currentBingo = updatedBingo;
        panel.displayBingoBoard(updatedBingo);

        // Rebuild requirement matcher lookup maps after bingo changes
        // The matcher will query currentBingo directly from the plugin
        requirementMatcher.rebuildLookupMaps();
    }

    private void showErrorMessage(String message) {
        clientThread.invokeLater(() ->
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "BingoScape: " + message, null));
    }

    private void showSuccessMessage(String message) {
        clientThread.invokeLater(() ->
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "BingoScape: " + message, null));
    }

    private boolean hasApiKey() {
        return config.apiKey() != null && !config.apiKey().isEmpty();
    }

    public void pinBingo(UUID bingoId) {
        config.pinnedBingoId(bingoId.toString());
    }

    public void unpinBingo() {
        config.pinnedBingoId("");
    }

    public BingoScapePanel getPanel() {
        return panel;
    }

    /**
     * Gets the current logged-in RuneScape account name.
     */
    public String getAccountName() {
        if (client != null && client.getLocalPlayer() != null) {
            return client.getLocalPlayer().getName();
        }
        return null;
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        autoSubmissionHandler.onNpcLootReceived(event);
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        autoSubmissionHandler.onLootReceived(event);
    }

    @Schedule(period = 60, unit = ChronoUnit.SECONDS)
    public void cleanupAutoSubmissionCooldowns() {
        autoSubmissionHandler.cleanupCooldowns();
    }

    @Provides
    BingoScapeConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BingoScapeConfig.class);
    }
}

package org.bingoscape;

/**
 * How the bingo board is displayed when opened from the side panel.
 */
public enum BoardDisplayMode {
    OVERLAY("In-game overlay"),
    WINDOW("Separate window (legacy)");

    private final String name;

    BoardDisplayMode(String name) {
        this.name = name;
    }

    @Override
    public String toString() {
        return name;
    }
}

package org.bingoscape.board;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ImageUtil;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.BoardDisplayMode;
import org.bingoscape.models.Bingo;
import org.bingoscape.models.Tile;
import org.bingoscape.models.TileSubmissionType;
import org.bingoscape.services.TileImageCache;
import org.bingoscape.ui.TileStatusStyle;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/**
 * In-game bingo board. Non-modal: it only takes input inside its own bounds (see {@link BoardInputListener}),
 * and can be moved with Alt-drag like any RuneLite overlay.
 */
@Singleton
public class BingoBoardOverlay extends Overlay {
    private static final int MIN_DETAIL_TILE_SIZE = 56;
    private static final int ICON_SIZE = 16;
    private static final long RELOAD_TIMEOUT_MS = 10_000;
    private static final String MENU_TARGET = "Bingo board";

    private final Client client;
    private final BingoScapePlugin plugin;
    private final BingoScapeConfig config;
    private final BoardState state;
    private final TileImageCache images;
    private final TooltipManager tooltipManager;
    private final ItemManager itemManager;
    private final BufferedImage refreshIcon;

    // Render-thread only
    private Bingo lastBingo;
    private BoardModel model;
    private final Map<String, List<String>> wrapMemo = new HashMap<>();
    private int lastTileSize = -1;

    private volatile HitMap hitMap;

    @Inject
    public BingoBoardOverlay(Client client, BingoScapePlugin plugin, BingoScapeConfig config, BoardState state,
                             TileImageCache images, TooltipManager tooltipManager, ItemManager itemManager) {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.state = state;
        this.images = images;
        this.tooltipManager = tooltipManager;
        this.itemManager = itemManager;
        this.refreshIcon = ImageUtil.loadImageResource(BingoScapePlugin.class, "/refresh_icon.png");

        setPosition(OverlayPosition.DETACHED);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
        setMovable(true);
        addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Close", MENU_TARGET, e -> plugin.hideBoard());
    }

    /**
     * Click regions from the last rendered frame, or null when the board is not drawn.
     */
    HitMap hitMap() {
        return hitMap;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Bingo bingo = plugin.getCurrentBingo();
        if (!state.isVisible() || state.isCaptureSuppressed()
                || config.boardDisplayMode() != BoardDisplayMode.OVERLAY || bingo == null) {
            hitMap = null;
            return null;
        }

        if (bingo != lastBingo) {
            rebuildModel(bingo);
        }

        if (state.isReloading() && System.currentTimeMillis() - state.getReloadStartedAtMs() > RELOAD_TIMEOUT_MS) {
            state.finishReload();
        }

        boolean hasCodephrase = bingo.getCodephrase() != null && !bingo.getCodephrase().trim().isEmpty();
        BoardLayout layout = BoardLayout.compute(bingo.getRows(), bingo.getColumns(), model.tiles.size(),
                client.getCanvasWidth(), client.getCanvasHeight(), config.boardScale() / 100.0, hasCodephrase);

        if (getPreferredLocation() == null) {
            setPreferredLocation(new Point(
                    Math.max(0, (client.getCanvasWidth() - layout.width) / 2),
                    Math.max(0, (client.getCanvasHeight() - layout.height) / 2)));
        }

        // Wrapped titles depend on tile size; drop them when it changes so the memo can't grow on resize
        if (layout.tileSize != lastTileSize) {
            wrapMemo.clear();
            lastTileSize = layout.tileSize;
        }

        // Copy the origin once per frame; the listener reads it from the hit map instead of getBounds()
        Point origin = getBounds().getLocation();
        Point mouse = localMouse(layout, origin);
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

            paintBackground(g, layout);
            BoardLayout.Button hoveredButton = mouse == null ? BoardLayout.Button.NONE : layout.buttonAt(mouse.x, mouse.y);
            paintHeader(g, layout, bingo, hoveredButton);

            Tile detailsTile = detailsTile();
            TileDetailsView.DetailsHit details = null;
            int hoveredTile = -1;
            if (detailsTile != null) {
                details = TileDetailsView.paint(g, layout.gridArea, detailsTile, bingo,
                        config.boardShowTileImages() ? images : null, itemManager::getImage,
                        state.getDetailsScrollPx(), mouse);
                if (state.getDetailsScrollPx() > details.maxScroll) {
                    state.setDetailsScrollPx(details.maxScroll);
                }
            } else {
                hoveredTile = mouse == null ? -1 : layout.tileIndexAt(mouse.x, mouse.y);
                paintGrid(g, layout, hoveredTile);
            }

            addTooltips(hoveredButton, hoveredTile, bingo);
            hitMap = new HitMap(origin, layout, model.tiles, detailsTile, details);
        } finally {
            g.dispose();
        }

        return new Dimension(layout.width, layout.height);
    }

    private void rebuildModel(Bingo bingo) {
        model = BoardModel.of(bingo);
        lastBingo = bingo;
        wrapMemo.clear();

        if (config.boardShowTileImages()) {
            List<String> urls = new ArrayList<>();
            for (Tile tile : model.tiles) {
                if (!tile.isHidden() && tile.getHeaderImage() != null && !tile.getHeaderImage().trim().isEmpty()) {
                    urls.add(tile.getHeaderImage());
                }
            }
            images.prefetch(urls);
        }
    }

    private Tile detailsTile() {
        UUID id = state.getDetailsTileId();
        if (id == null) {
            return null;
        }

        Tile tile = model.byId.get(id);
        if (tile == null || tile.isHidden()) {
            // Tile vanished after a refresh or bingo switch
            state.closeDetails();
            return null;
        }
        return tile;
    }

    /**
     * Mouse position relative to the overlay origin, or null when the mouse is outside the canvas.
     */
    private Point localMouse(BoardLayout layout, Point origin) {
        net.runelite.api.Point canvasMouse = client.getMouseCanvasPosition();
        Point mouse = canvasMouse != null && canvasMouse.getX() >= 0
                ? new Point(canvasMouse.getX(), canvasMouse.getY())
                : state.getLastMouse();
        if (mouse == null) {
            return null;
        }

        Point local = new Point(mouse.x - origin.x, mouse.y - origin.y);
        return layout.contains(local.x, local.y) ? local : null;
    }

    private void paintBackground(Graphics2D g, BoardLayout layout) {
        int alpha = Math.round(config.boardOpacity() * 255 / 100f);
        Graphics2D bg = (Graphics2D) g.create();
        try {
            bg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            bg.setColor(BoardDraw.withAlpha(ColorScheme.DARK_GRAY_COLOR, alpha));
            bg.fillRoundRect(0, 0, layout.width, layout.height, 8, 8);
            bg.setColor(ColorScheme.BORDER_COLOR);
            bg.drawRoundRect(0, 0, layout.width - 1, layout.height - 1, 8, 8);

            Rectangle grid = layout.gridArea;
            bg.setColor(BoardDraw.withAlpha(ColorScheme.DARKER_GRAY_COLOR, alpha));
            bg.fillRect(grid.x - 2, grid.y - 2, grid.width + 4, grid.height + 4);
        } finally {
            bg.dispose();
        }
    }

    private void paintHeader(Graphics2D g, BoardLayout layout, Bingo bingo, BoardLayout.Button hovered) {
        // Title, with a gray [Locked] suffix like the side panel
        g.setFont(FontManager.getRunescapeBoldFont());
        FontMetrics fm = g.getFontMetrics();
        String suffix = bingo.isLocked() ? " [Locked]" : "";
        int suffixWidth = fm.stringWidth(suffix);
        String title = TextWrap.ellipsize(bingo.getTitle(), fm, Math.max(0, layout.title.width - suffixWidth));
        int baseline = layout.title.y + (layout.title.height - fm.getHeight()) / 2 + fm.getAscent();
        BoardDraw.text(g, title, layout.title.x, baseline, Color.WHITE);
        if (!suffix.isEmpty()) {
            BoardDraw.text(g, suffix, layout.title.x + fm.stringWidth(title), baseline, Color.GRAY);
        }

        if (layout.codephrase != null) {
            g.setFont(FontManager.getRunescapeSmallFont());
            FontMetrics small = g.getFontMetrics();
            String codephrase = TextWrap.ellipsize("Codephrase: " + bingo.getCodephrase().trim(), small, layout.codephrase.width);
            BoardDraw.text(g, codephrase, layout.codephrase.x, layout.codephrase.y + small.getAscent(), BoardTooltipBuilder.GOLD);
        }

        // Pin
        g.setFont(FontManager.getRunescapeSmallFont());
        BoardDraw.button(g, layout.pinButton, hovered == BoardLayout.Button.PIN, true);
        BoardDraw.centeredText(g, isPinned(bingo) ? "Unpin" : "Pin", layout.pinButton, Color.WHITE);

        // Reload, dimmed while a reload is running
        boolean reloading = state.isReloading();
        BoardDraw.button(g, layout.reloadButton, hovered == BoardLayout.Button.RELOAD, !reloading);
        if (refreshIcon != null) {
            Rectangle r = layout.reloadButton;
            Graphics2D ig = (Graphics2D) g.create();
            try {
                ig.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, reloading ? 0.35f : 1f));
                ig.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                ig.drawImage(refreshIcon, r.x + (r.width - ICON_SIZE) / 2, r.y + (r.height - ICON_SIZE) / 2, ICON_SIZE, ICON_SIZE, null);
            } finally {
                ig.dispose();
            }
        }

        // Close
        BoardDraw.button(g, layout.closeButton, hovered == BoardLayout.Button.CLOSE, true);
        BoardDraw.closeIcon(g, layout.closeButton, hovered == BoardLayout.Button.CLOSE);
    }

    private void paintGrid(Graphics2D g, BoardLayout layout, int hoveredTile) {
        for (int i = 0; i < layout.tiles.size() && i < model.tiles.size(); i++) {
            Rectangle r = layout.tiles.get(i);
            Tile tile = model.tiles.get(i);
            Graphics2D tg = (Graphics2D) g.create();
            try {
                tg.clipRect(r.x, r.y, r.width, r.height);
                if (tile.isHidden()) {
                    paintHiddenTile(tg, r);
                } else {
                    paintTile(tg, r, tile, i == hoveredTile);
                }
            } finally {
                tg.dispose();
            }
        }
    }

    private void paintHiddenTile(Graphics2D g, Rectangle r) {
        g.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g.fillRect(r.x, r.y, r.width, r.height);
        g.setColor(ColorScheme.BORDER_COLOR);
        g.drawRect(r.x, r.y, r.width - 1, r.height - 1);

        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setFont(FontManager.getDefaultBoldFont().deriveFont(Font.BOLD, 24f));
        BoardDraw.centeredText(g, "?", r, Color.GRAY);
    }

    private void paintTile(Graphics2D g, Rectangle r, Tile tile, boolean hovered) {
        TileSubmissionType status = TileStatusStyle.statusOf(tile);
        Color background = TileStatusStyle.background(status);
        g.setColor(hovered ? background.brighter() : background);
        g.fillRect(r.x, r.y, r.width, r.height);
        g.setColor(TileStatusStyle.border(status));
        g.setStroke(new BasicStroke(2));
        g.drawRect(r.x + 1, r.y + 1, r.width - 2, r.height - 2);

        Rectangle inner = new Rectangle(r.x + 4, r.y + 4, r.width - 8, r.height - 8);
        boolean showDetails = r.width >= MIN_DETAIL_TILE_SIZE;
        int top = inner.y;
        int bottom = inner.y + inner.height;

        if (showDetails) {
            g.setFont(FontManager.getRunescapeSmallFont());
            FontMetrics fm = g.getFontMetrics();
            String xp = tile.getWeight() + " XP";
            BoardDraw.text(g, xp, inner.x + inner.width - fm.stringWidth(xp), inner.y + fm.getAscent(), BoardTooltipBuilder.GOLD);
            top += fm.getHeight();

            String label = TileStatusStyle.shortLabel(status);
            if (label != null) {
                g.setFont(FontManager.getRunescapeBoldFont());
                FontMetrics bold = g.getFontMetrics();
                String fitted = TextWrap.ellipsize(label, bold, inner.width);
                bottom -= bold.getHeight();
                BoardDraw.text(g, fitted, inner.x + (inner.width - bold.stringWidth(fitted)) / 2,
                        bottom + bold.getAscent(), TileStatusStyle.border(status));
            }
        }

        Rectangle content = new Rectangle(inner.x, top, inner.width, Math.max(0, bottom - top));
        paintTileContent(g, content, tile);
    }

    private void paintTileContent(Graphics2D g, Rectangle box, Tile tile) {
        String url = tile.getHeaderImage();
        if (config.boardShowTileImages() && url != null && !url.trim().isEmpty() && !images.hasFailed(url)) {
            BufferedImage image = images.getScaled(url, box.width, box.height);
            if (image != null) {
                g.drawImage(image, box.x + (box.width - image.getWidth()) / 2, box.y + (box.height - image.getHeight()) / 2, null);
                return;
            }

            // Scaled copy not ready yet (first frame or after a resize): draw the source scaled on the fly
            BufferedImage source = images.getSource(url);
            if (source != null) {
                Rectangle target = BoardDraw.fitted(source.getWidth(), source.getHeight(), box);
                Graphics2D ig = (Graphics2D) g.create();
                try {
                    ig.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                    ig.drawImage(source, target.x, target.y, target.width, target.height, null);
                } finally {
                    ig.dispose();
                }
                return;
            }

            g.setFont(FontManager.getRunescapeSmallFont());
            BoardDraw.centeredText(g, "Loading...", box, Color.LIGHT_GRAY);
            return;
        }

        paintTileTitle(g, box, tile);
    }

    private void paintTileTitle(Graphics2D g, Rectangle box, Tile tile) {
        g.setFont(TextWrap.displayable(FontManager.getRunescapeFont(), tile.getTitle()));
        FontMetrics fm = g.getFontMetrics();
        int maxLines = Math.max(1, box.height / fm.getHeight());
        // Keyed by text, not tile id: ids may be null, and equal titles wrap identically
        String key = tile.getTitle() + "|" + box.width + "|" + maxLines;
        List<String> lines = wrapMemo.computeIfAbsent(key, k -> TextWrap.wrap(tile.getTitle(), fm, box.width, maxLines));

        int y = box.y + (box.height - lines.size() * fm.getHeight()) / 2;
        for (String line : lines) {
            BoardDraw.text(g, line, box.x + (box.width - fm.stringWidth(line)) / 2, y + fm.getAscent(), Color.WHITE);
            y += fm.getHeight();
        }
    }

    private void addTooltips(BoardLayout.Button hoveredButton, int hoveredTile, Bingo bingo) {
        switch (hoveredButton) {
            case PIN:
                tooltipManager.add(new Tooltip(isPinned(bingo) ? "Unpin board" : "Pin board"));
                return;
            case RELOAD:
                tooltipManager.add(new Tooltip(state.isReloading() ? "Reloading..." : "Reload board"));
                return;
            case CLOSE:
                tooltipManager.add(new Tooltip("Close board"));
                return;
            default:
                break;
        }

        if (config.boardShowTooltips() && hoveredTile >= 0 && hoveredTile < model.tiles.size()) {
            Tile tile = model.tiles.get(hoveredTile);
            tooltipManager.add(tile.isHidden()
                    ? new Tooltip(BoardTooltipBuilder.build(tile))
                    : new Tooltip(new TileHoverCard(tile, itemManager::getImage)));
        }
    }

    private boolean isPinned(Bingo bingo) {
        return bingo.getId() != null && bingo.getId().toString().equals(config.pinnedBingoId());
    }
}

package org.bingoscape.board;

import org.bingoscape.ui.BingoTheme;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;

/**
 * Small drawing primitives shared by the board overlay painters.
 */
final class BoardDraw {
    private static final Color SHADOW = Color.BLACK;
    private static final Color BUTTON_BG = BingoTheme.BUTTON_BACKGROUND;
    private static final Color BUTTON_HOVER = BingoTheme.BUTTON_HOVER;
    private static final Color BUTTON_BORDER = BingoTheme.BUTTON_BORDER;

    static final Color FOREGROUND = BingoTheme.FOREGROUND;
    static final Color MUTED = BingoTheme.MUTED;
    static final Color PROGRESS_COMPLETE = BingoTheme.PROGRESS_COMPLETE;
    static final Color PROGRESS_PARTIAL = BingoTheme.PROGRESS_PARTIAL;
    static final Color PROGRESS_BG = BingoTheme.PROGRESS_BACKGROUND;

    private BoardDraw() {
    }

    /**
     * Draws text with a 1px drop shadow, the usual RuneLite overlay style.
     */
    static void text(Graphics2D g, String text, int x, int baseline, Color color) {
        Font font = g.getFont();
        g.setFont(TextWrap.displayable(font, text));
        g.setColor(SHADOW);
        g.drawString(text, x + 1, baseline + 1);
        g.setColor(color);
        g.drawString(text, x, baseline);
        g.setFont(font);
    }

    static void centeredText(Graphics2D g, String text, Rectangle box, Color color) {
        FontMetrics fm = g.getFontMetrics();
        int x = box.x + (box.width - fm.stringWidth(text)) / 2;
        int baseline = box.y + (box.height - fm.getHeight()) / 2 + fm.getAscent();
        text(g, text, x, baseline, color);
    }

    static void button(Graphics2D g, Rectangle r, boolean hover, boolean enabled) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(enabled ? BUTTON_BG : withAlpha(BUTTON_BG, 120));
            g2.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
            if (hover && enabled) {
                g2.setColor(BUTTON_HOVER);
                g2.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
            }
            g2.setColor(BUTTON_BORDER);
            g2.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, 6, 6);
        } finally {
            g2.dispose();
        }
    }

    static int pillHeight(Graphics2D g) {
        return g.getFontMetrics().getHeight() + 2;
    }

    /**
     * Rounded status pill with the text in {@code accent}, like the AND/OR badges. Returns the pill width.
     */
    static int pill(Graphics2D g, String text, int x, int y, Color accent) {
        FontMetrics fm = g.getFontMetrics();
        int width = fm.stringWidth(text) + 12;
        int height = pillHeight(g);
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(withAlpha(accent, 50));
            g2.fillRoundRect(x, y, width - 1, height - 1, height, height);
            g2.setColor(withAlpha(accent, 140));
            g2.drawRoundRect(x, y, width - 1, height - 1, height, height);
        } finally {
            g2.dispose();
        }
        text(g, text, x + 6, y + 1 + fm.getAscent(), accent);
        return width;
    }

    static void closeIcon(Graphics2D g, Rectangle r, boolean hover) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int pad = Math.max(5, r.width * 3 / 10);
            int x1 = r.x + pad;
            int y1 = r.y + pad;
            int x2 = r.x + r.width - pad;
            int y2 = r.y + r.height - pad;
            g2.setStroke(new BasicStroke(1.75f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g2.setColor(new Color(0, 0, 0, 120));
            g2.drawLine(x1 + 1, y1 + 1, x2 + 1, y2 + 1);
            g2.drawLine(x2 + 1, y1 + 1, x1 + 1, y2 + 1);
            g2.setColor(hover ? Color.WHITE : Color.LIGHT_GRAY);
            g2.drawLine(x1, y1, x2, y2);
            g2.drawLine(x2, y1, x1, y2);
        } finally {
            g2.dispose();
        }
    }

    /**
     * Returns the largest rectangle with the image's aspect ratio that fits in {@code box}, centered.
     */
    static Rectangle fitted(int imageWidth, int imageHeight, Rectangle box) {
        if (imageWidth <= 0 || imageHeight <= 0 || box.width <= 0 || box.height <= 0) {
            return new Rectangle(box.x, box.y, 0, 0);
        }
        double ratio = Math.min((double) box.width / imageWidth, (double) box.height / imageHeight);
        int width = Math.max(1, (int) Math.round(imageWidth * ratio));
        int height = Math.max(1, (int) Math.round(imageHeight * ratio));
        return new Rectangle(box.x + (box.width - width) / 2, box.y + (box.height - height) / 2, width, height);
    }

    /**
     * Thin progress bar from the web app's compact goal tree: gray when nothing is done,
     * amber when partially done, green when complete.
     */
    static void progressBar(Graphics2D g, int x, int y, int width, int height, int current, int target, boolean complete) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(PROGRESS_BG);
            g2.fillRoundRect(x, y, width, height, 3, 3);
            if (target > 0) {
                int fill = (int) (width * Math.min(1.0, (double) current / target));
                g2.setColor(progressColor(current, complete));
                g2.fillRoundRect(x, y, fill, height, 3, 3);
            }
        } finally {
            g2.dispose();
        }
    }

    static Color progressColor(int current, boolean complete) {
        return BingoTheme.progressColor(current, complete);
    }

    static Color progressTextColor(int current, boolean complete, boolean hasProgress) {
        if (!hasProgress) {
            return MUTED;
        }
        if (complete) {
            return PROGRESS_COMPLETE;
        }
        return current > 0 ? PROGRESS_PARTIAL : MUTED;
    }

    static Color withAlpha(Color color, int alpha) {
        return BingoTheme.withAlpha(color, alpha);
    }
}

package org.bingoscape.board;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.models.Tile;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Point;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;

/**
 * Routes mouse and keyboard input to the board overlay. Unlike a modal overlay, only events inside the
 * board are consumed; mouse movement is never consumed so the client keeps tracking the cursor.
 * Callbacks run on the AWT event thread.
 */
@Singleton
public class BoardInputListener implements MouseListener, MouseWheelListener, KeyListener {
    private static final int SCROLL_STEP_PX = 16;
    private static final int SCALE_STEP = 10;
    private static final int MIN_SCALE = 50;
    private static final int MAX_SCALE = 200;

    private final BingoBoardOverlay overlay;
    private final BoardState state;
    private final BingoScapePlugin plugin;
    private final BingoScapeConfig config;
    private final ConfigManager configManager;

    // A press consumed by the board also consumes its release, so the game never sees half a click
    private volatile boolean pressStartedInside;

    @Inject
    public BoardInputListener(BingoBoardOverlay overlay, BoardState state, BingoScapePlugin plugin,
                              BingoScapeConfig config, ConfigManager configManager) {
        this.overlay = overlay;
        this.state = state;
        this.plugin = plugin;
        this.config = config;
        this.configManager = configManager;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent e) {
        state.setLastMouse(e.getPoint());
        HitMap hitMap = overlay.hitMap();
        Point p = toLocal(e, hitMap);
        // Alt is RuneLite's overlay drag modifier; right click must reach the game to open the overlay menu
        if (p == null || e.isAltDown() || e.getButton() == MouseEvent.BUTTON3) {
            return e;
        }

        if (e.getButton() == MouseEvent.BUTTON1) {
            handleLeftClick(hitMap, p);
        }

        pressStartedInside = true;
        e.consume();
        return e;
    }

    private void handleLeftClick(HitMap hitMap, Point p) {
        switch (hitMap.layout.buttonAt(p.x, p.y)) {
            case PIN:
                plugin.toggleBoardPin();
                return;
            case RELOAD:
                if (!state.isReloading()) {
                    plugin.reloadBoard();
                }
                return;
            case CLOSE:
                plugin.hideBoard();
                return;
            default:
                break;
        }

        TileDetailsView.DetailsHit details = hitMap.details;
        if (details != null) {
            if (details.closeButton.contains(p)) {
                state.closeDetails();
            } else if (details.primaryButton.contains(p) && details.primaryEnabled) {
                Tile tile = hitMap.detailsTile;
                state.closeDetails();
                plugin.captureAndPreviewSubmission(tile);
            }
            return;
        }

        Tile tile = hitMap.tileAt(p.x, p.y);
        if (tile != null && !tile.isHidden() && tile.getId() != null) {
            state.openDetails(tile.getId());
        }
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent e) {
        if (pressStartedInside) {
            pressStartedInside = false;
            e.consume();
        }
        return e;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent e) {
        Point p = toLocal(e, overlay.hitMap());
        if (p != null && !e.isAltDown() && e.getButton() == MouseEvent.BUTTON1) {
            e.consume();
        }
        return e;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent e) {
        return e;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent e) {
        state.setLastMouse(null);
        return e;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent e) {
        state.setLastMouse(e.getPoint());
        return e;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent e) {
        state.setLastMouse(e.getPoint());
        return e;
    }

    @Override
    public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e) {
        HitMap hitMap = overlay.hitMap();
        if (toLocal(e, hitMap) == null) {
            return e;
        }

        if (hitMap.details != null) {
            state.setDetailsScrollPx(state.getDetailsScrollPx() + e.getWheelRotation() * SCROLL_STEP_PX);
        } else if (e.isControlDown()) {
            int scale = config.boardScale() - e.getWheelRotation() * SCALE_STEP;
            scale = Math.max(MIN_SCALE, Math.min(MAX_SCALE, scale));
            configManager.setConfiguration(BingoScapeConfig.CONFIG_GROUP, "boardScale", scale);
        }

        // Never let the wheel zoom the camera while over the board
        e.consume();
        return e;
    }

    @Override
    public void keyPressed(KeyEvent e) {
        if (e.getKeyCode() != KeyEvent.VK_ESCAPE || !config.boardCloseOnEscape() || overlay.hitMap() == null) {
            return;
        }

        if (state.getDetailsTileId() != null) {
            state.closeDetails();
        } else {
            plugin.hideBoard();
        }
        e.consume();
    }

    @Override
    public void keyTyped(KeyEvent e) {
    }

    @Override
    public void keyReleased(KeyEvent e) {
    }

    /**
     * Converts a canvas point to overlay coordinates, or null when the board is hidden or the point is outside it.
     */
    private Point toLocal(MouseEvent e, HitMap hitMap) {
        if (hitMap == null) {
            return null;
        }

        int x = e.getX() - hitMap.origin.x;
        int y = e.getY() - hitMap.origin.y;
        return hitMap.layout.contains(x, y) ? new Point(x, y) : null;
    }
}

package org.bingoscape.board;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Pure layout math for the board overlay. All rectangles are relative to the overlay origin.
 */
final class BoardLayout {
    static final int PAD = 10;
    static final int GAP = 4;
    static final int TITLE_HEIGHT = 24;
    static final int CODEPHRASE_HEIGHT = 14;
    static final int HEADER_SPACING = 6;
    static final int TILE_DEFAULT = 96;
    static final int TILE_MIN = 40;
    static final int DEFAULT_GRID_SIZE = 5;
    static final int BUTTON_SIZE = 20;
    static final int PIN_BUTTON_WIDTH = 44;
    static final int MIN_WIDTH = 240;
    static final double VIEWPORT_FILL = 0.9;

    enum Button {
        PIN, RELOAD, CLOSE, NONE
    }

    final int rows;
    final int cols;
    final int width;
    final int height;
    final int tileSize;
    final Rectangle title;
    final Rectangle codephrase;
    final Rectangle pinButton;
    final Rectangle reloadButton;
    final Rectangle closeButton;
    final Rectangle gridArea;
    final List<Rectangle> tiles;

    private BoardLayout(int rows, int cols, int width, int height, int tileSize, Rectangle title, Rectangle codephrase,
                        Rectangle pinButton, Rectangle reloadButton, Rectangle closeButton, Rectangle gridArea,
                        List<Rectangle> tiles) {
        this.rows = rows;
        this.cols = cols;
        this.width = width;
        this.height = height;
        this.tileSize = tileSize;
        this.title = title;
        this.codephrase = codephrase;
        this.pinButton = pinButton;
        this.reloadButton = reloadButton;
        this.closeButton = closeButton;
        this.gridArea = gridArea;
        this.tiles = tiles;
    }

    static BoardLayout compute(int rows, int cols, int tileCount, int viewportWidth, int viewportHeight,
                               double scale, boolean hasCodephrase) {
        int effectiveCols = cols <= 0 ? DEFAULT_GRID_SIZE : cols;
        int effectiveRows = rows <= 0 ? DEFAULT_GRID_SIZE : rows;
        // Like GridLayout, grow the grid when there are more tiles than cells
        effectiveRows = Math.max(effectiveRows, (tileCount + effectiveCols - 1) / effectiveCols);

        int headerHeight = TITLE_HEIGHT + (hasCodephrase ? CODEPHRASE_HEIGHT : 0) + HEADER_SPACING;
        int availableWidth = (int) (viewportWidth * VIEWPORT_FILL) - 2 * PAD;
        int availableHeight = (int) (viewportHeight * VIEWPORT_FILL) - 2 * PAD - headerHeight;
        int fitWidth = (availableWidth - (effectiveCols - 1) * GAP) / effectiveCols;
        int fitHeight = (availableHeight - (effectiveRows - 1) * GAP) / effectiveRows;
        int preferred = (int) Math.round(TILE_DEFAULT * scale);
        int tileSize = Math.max(TILE_MIN, Math.min(preferred, Math.min(fitWidth, fitHeight)));

        int gridWidth = effectiveCols * tileSize + (effectiveCols - 1) * GAP;
        int gridHeight = effectiveRows * tileSize + (effectiveRows - 1) * GAP;
        int width = Math.max(MIN_WIDTH, 2 * PAD + gridWidth);
        int height = 2 * PAD + headerHeight + gridHeight;

        int buttonY = PAD + (TITLE_HEIGHT - BUTTON_SIZE) / 2;
        Rectangle closeButton = new Rectangle(width - PAD - BUTTON_SIZE, buttonY, BUTTON_SIZE, BUTTON_SIZE);
        Rectangle reloadButton = new Rectangle(closeButton.x - GAP - BUTTON_SIZE, buttonY, BUTTON_SIZE, BUTTON_SIZE);
        Rectangle pinButton = new Rectangle(reloadButton.x - GAP - PIN_BUTTON_WIDTH, buttonY, PIN_BUTTON_WIDTH, BUTTON_SIZE);
        Rectangle title = new Rectangle(PAD, PAD, Math.max(0, pinButton.x - GAP - PAD), TITLE_HEIGHT);
        Rectangle codephrase = hasCodephrase
                ? new Rectangle(PAD, PAD + TITLE_HEIGHT, width - 2 * PAD, CODEPHRASE_HEIGHT)
                : null;

        int gridX = (width - gridWidth) / 2;
        int gridY = PAD + headerHeight;
        Rectangle gridArea = new Rectangle(gridX, gridY, gridWidth, gridHeight);

        List<Rectangle> tiles = new ArrayList<>(effectiveRows * effectiveCols);
        for (int i = 0; i < effectiveRows * effectiveCols; i++) {
            int x = gridX + (i % effectiveCols) * (tileSize + GAP);
            int y = gridY + (i / effectiveCols) * (tileSize + GAP);
            tiles.add(new Rectangle(x, y, tileSize, tileSize));
        }

        return new BoardLayout(effectiveRows, effectiveCols, width, height, tileSize, title, codephrase,
                pinButton, reloadButton, closeButton, gridArea, Collections.unmodifiableList(tiles));
    }

    /**
     * Returns the tile index under the point, or -1 for gaps and points outside the grid.
     */
    int tileIndexAt(int x, int y) {
        if (!gridArea.contains(x, y)) {
            return -1;
        }

        int step = tileSize + GAP;
        int dx = x - gridArea.x;
        int dy = y - gridArea.y;
        if (dx % step >= tileSize || dy % step >= tileSize) {
            return -1;
        }

        int col = dx / step;
        int row = dy / step;
        if (col >= cols || row >= rows) {
            return -1;
        }
        return row * cols + col;
    }

    Button buttonAt(int x, int y) {
        if (pinButton.contains(x, y)) {
            return Button.PIN;
        }
        if (reloadButton.contains(x, y)) {
            return Button.RELOAD;
        }
        if (closeButton.contains(x, y)) {
            return Button.CLOSE;
        }
        return Button.NONE;
    }

    boolean contains(int x, int y) {
        return x >= 0 && y >= 0 && x < width && y < height;
    }
}

package org.bingoscape.board;

import org.bingoscape.models.Bingo;
import org.bingoscape.models.Tile;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

/**
 * Immutable snapshot of a bingo board for rendering. Tiles are a sorted copy, so the shared
 * {@link Bingo#getTiles()} list is never mutated.
 */
final class BoardModel {
    final Bingo bingo;
    final List<Tile> tiles;
    final Map<UUID, Tile> byId;

    private BoardModel(Bingo bingo, List<Tile> tiles, Map<UUID, Tile> byId) {
        this.bingo = bingo;
        this.tiles = tiles;
        this.byId = byId;
    }

    static BoardModel of(Bingo bingo) {
        List<Tile> tiles = bingo.getTiles() == null ? new ArrayList<>() : new ArrayList<>(bingo.getTiles());
        tiles.removeIf(Objects::isNull);
        tiles.sort(Comparator.comparingInt(Tile::getIndex));

        Map<UUID, Tile> byId = new HashMap<>();
        for (Tile tile : tiles) {
            if (tile.getId() != null) {
                byId.put(tile.getId(), tile);
            }
        }

        return new BoardModel(bingo, Collections.unmodifiableList(tiles), Collections.unmodifiableMap(byId));
    }
}

package org.bingoscape.board;

import javax.inject.Singleton;
import java.awt.Point;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Board overlay UI state. Written from the EDT (input, side panel) and read by the client thread
 * (render), so every field is volatile or atomic.
 */
@Singleton
public class BoardState {
    private volatile boolean visible;
    private final AtomicInteger pendingCaptures = new AtomicInteger();
    private volatile UUID detailsTileId;
    private volatile int detailsScrollPx;
    private volatile boolean reloading;
    private volatile long reloadStartedAtMs;
    private volatile Point lastMouse;

    public boolean isVisible() {
        return visible;
    }

    public void show() {
        visible = true;
    }

    public void hide() {
        visible = false;
        reset();
    }

    public void reset() {
        detailsTileId = null;
        detailsScrollPx = 0;
        reloading = false;
    }

    /**
     * True while at least one screenshot capture is pending; the board must not be drawn into it.
     */
    public boolean isCaptureSuppressed() {
        return pendingCaptures.get() > 0;
    }

    public void beginCapture() {
        pendingCaptures.incrementAndGet();
    }

    public void endCapture() {
        pendingCaptures.updateAndGet(count -> Math.max(0, count - 1));
    }

    public void resetCaptures() {
        pendingCaptures.set(0);
    }

    public UUID getDetailsTileId() {
        return detailsTileId;
    }

    public void openDetails(UUID tileId) {
        detailsScrollPx = 0;
        detailsTileId = tileId;
    }

    public void closeDetails() {
        detailsTileId = null;
        detailsScrollPx = 0;
    }

    public int getDetailsScrollPx() {
        return detailsScrollPx;
    }

    public void setDetailsScrollPx(int detailsScrollPx) {
        this.detailsScrollPx = Math.max(0, detailsScrollPx);
    }

    public boolean isReloading() {
        return reloading;
    }

    public void startReload() {
        reloadStartedAtMs = System.currentTimeMillis();
        reloading = true;
    }

    public void finishReload() {
        reloading = false;
    }

    public long getReloadStartedAtMs() {
        return reloadStartedAtMs;
    }

    public Point getLastMouse() {
        return lastMouse;
    }

    public void setLastMouse(Point lastMouse) {
        this.lastMouse = lastMouse;
    }
}

package org.bingoscape.board;

import net.runelite.client.util.ColorUtil;
import org.bingoscape.models.Goal;
import org.bingoscape.models.Tile;
import org.bingoscape.models.TileSubmission;
import org.bingoscape.ui.BingoTheme;
import org.bingoscape.ui.TileStatusStyle;

import java.awt.Color;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.List;

/**
 * Builds RuneLite tooltip text (color tags, {@code </br>} line breaks) for board tiles.
 */
final class BoardTooltipBuilder {
    static final Color GOLD = BingoTheme.GOLD;
    private static final String BR = "</br>";
    private static final int DESCRIPTION_LINE_CHARS = 45;
    private static final int MAX_GOALS = 8;

    private BoardTooltipBuilder() {
    }

    static String build(Tile tile) {
        if (tile.isHidden()) {
            return "Hidden tile";
        }

        StringBuilder text = new StringBuilder();
        text.append(ColorUtil.wrapWithColorTag(sanitize(tile.getTitle()) + " (" + tile.getWeight() + " XP)", GOLD));

        if (tile.getDescription() != null && !tile.getDescription().trim().isEmpty()) {
            for (String line : wrapChars(sanitize(tile.getDescription()), DESCRIPTION_LINE_CHARS)) {
                text.append(BR).append(line);
            }
        }

        TileSubmission submission = tile.getSubmission();
        if (submission != null && submission.getStatus() != null) {
            text.append(BR).append("Status: ")
                    .append("<col=").append(TileStatusStyle.hex(submission.getStatus()).substring(1)).append('>')
                    .append(TileStatusStyle.displayText(submission.getStatus()))
                    .append("</col>");

            if (submission.getSubmissionCount() > 0) {
                text.append(BR).append("Submissions: ").append(submission.getSubmissionCount());
            }

            if (submission.getLastUpdated() != null) {
                SimpleDateFormat dateFormat = new SimpleDateFormat("MMM dd, yyyy HH:mm");
                text.append(BR).append("Last updated: ").append(dateFormat.format(submission.getLastUpdated()));
            }
        }

        List<Goal> goals = tile.getGoals();
        if (goals != null && !goals.isEmpty()) {
            text.append(BR).append("Goals:");
            for (int i = 0; i < goals.size() && i < MAX_GOALS; i++) {
                Goal goal = goals.get(i);
                text.append(BR).append("- ").append(sanitize(goal.getDescription())).append(": ").append(goal.getTargetValue());
            }
            if (goals.size() > MAX_GOALS) {
                text.append(BR).append("+").append(goals.size() - MAX_GOALS).append(" more");
            }
        }

        return text.toString();
    }

    /**
     * The tooltip renderer treats anything in angle brackets as a tag, so user text must not contain them.
     */
    static String sanitize(String text) {
        if (text == null) {
            return "";
        }
        return text.replace('<', '(').replace('>', ')').replaceAll("\\s+", " ").trim();
    }

    private static List<String> wrapChars(String text, int maxChars) {
        List<String> lines = new ArrayList<>();
        StringBuilder line = new StringBuilder();
        for (String word : text.split(" ")) {
            if (line.length() > 0 && line.length() + 1 + word.length() > maxChars) {
                lines.add(line.toString());
                line.setLength(0);
            }
            if (line.length() > 0) {
                line.append(' ');
            }
            line.append(word);
        }
        if (line.length() > 0) {
            lines.add(line.toString());
        }
        return lines;
    }
}

package org.bingoscape.board;

import org.bingoscape.models.Tile;

import java.awt.Point;
import java.util.List;

/**
 * Immutable snapshot of the board's clickable regions, published by the render thread and read by
 * the input listener. Coordinates are relative to the overlay origin.
 */
final class HitMap {
    /** Overlay position on the canvas when this frame was rendered. */
    final Point origin;
    final BoardLayout layout;
    final List<Tile> tiles;
    final Tile detailsTile;
    final TileDetailsView.DetailsHit details;

    HitMap(Point origin, BoardLayout layout, List<Tile> tiles, Tile detailsTile, TileDetailsView.DetailsHit details) {
        this.origin = origin;
        this.layout = layout;
        this.tiles = tiles;
        this.detailsTile = detailsTile;
        this.details = details;
    }

    Tile tileAt(int x, int y) {
        int index = layout.tileIndexAt(x, y);
        return index >= 0 && index < tiles.size() ? tiles.get(index) : null;
    }
}

package org.bingoscape.board;

import net.runelite.client.ui.ColorScheme;
import org.bingoscape.models.Tile;

import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.WindowConstants;
import java.awt.BorderLayout;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Toolkit;
import java.awt.Window;
import java.util.function.Consumer;

/**
 * Confirm step before a manual tile submission: shows the captured screenshot with Cancel / Submit.
 * Must be created on the EDT.
 */
public final class ScreenshotPreviewDialog {
    private static final int MARGIN = 80;

    private ScreenshotPreviewDialog() {
    }

    /**
     * Builds the modal preview. The caller shows it with {@code setVisible(true)}.
     *
     * @param onSubmit called with the screenshot when the user confirms
     */
    public static JDialog create(Window owner, Tile tile, byte[] screenshotPng, Consumer<byte[]> onSubmit) {
        JDialog dialog = new JDialog(owner, "Submit: " + tile.getTitle(), Dialog.ModalityType.APPLICATION_MODAL);
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setLayout(new BorderLayout());

        ImageIcon icon = new ImageIcon(screenshotPng);
        JScrollPane scrollPane = new JScrollPane(new JLabel(icon));
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        scrollPane.getHorizontalScrollBar().setUnitIncrement(16);
        dialog.add(scrollPane, BorderLayout.CENTER);

        JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
        buttonPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JButton cancelButton = new JButton("Cancel");
        JButton submitButton = new JButton("Submit");
        cancelButton.addActionListener(e -> dialog.dispose());
        submitButton.addActionListener(e -> {
            dialog.dispose();
            onSubmit.accept(screenshotPng);
        });
        buttonPanel.add(cancelButton);
        buttonPanel.add(submitButton);
        dialog.add(buttonPanel, BorderLayout.SOUTH);

        // Show the whole screenshot when it fits, but never exceed 80% of the screen
        Dimension screen = Toolkit.getDefaultToolkit().getScreenSize();
        int width = Math.min(icon.getIconWidth() + MARGIN, (int) (screen.width * 0.8));
        int height = Math.min(icon.getIconHeight() + MARGIN + 40, (int) (screen.height * 0.8));
        dialog.setSize(Math.max(400, width), Math.max(300, height));
        dialog.setLocationRelativeTo(owner);
        dialog.getRootPane().setDefaultButton(submitButton);
        return dialog;
    }
}

package org.bingoscape.board;

import net.runelite.client.ui.FontManager;

import java.awt.Font;
import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.List;

/**
 * Text measuring helpers for the board overlay.
 */
final class TextWrap {
    // RuneScape fonts have no single-character ellipsis glyph
    static final String ELLIPSIS = "...";
    private static final float FALLBACK_FONT_SCALE = 0.8f;

    private TextWrap() {
    }

    /**
     * Word-wraps text to {@code maxWidth}. Words wider than a line are hard-broken. If the result
     * exceeds {@code maxLines}, the last kept line ends with an ellipsis.
     */
    static List<String> wrap(String text, FontMetrics fm, int maxWidth, int maxLines) {
        List<String> lines = new ArrayList<>();
        if (text == null || text.trim().isEmpty() || maxWidth <= 0 || maxLines <= 0) {
            return lines;
        }

        for (String paragraph : text.trim().split("\\r?\\n")) {
            StringBuilder line = new StringBuilder();
            for (String word : paragraph.trim().split("\\s+")) {
                if (word.isEmpty()) {
                    continue;
                }

                String candidate = line.length() == 0 ? word : line + " " + word;
                if (fm.stringWidth(candidate) <= maxWidth) {
                    line.setLength(0);
                    line.append(candidate);
                    continue;
                }

                if (line.length() > 0) {
                    lines.add(line.toString());
                    line.setLength(0);
                }

                while (word.length() > 1 && fm.stringWidth(word) > maxWidth) {
                    int cut = fittingChars(word, fm, maxWidth);
                    lines.add(word.substring(0, cut));
                    word = word.substring(cut);
                }
                line.append(word);
            }
            lines.add(line.toString());
        }

        if (lines.size() <= maxLines) {
            return lines;
        }

        List<String> truncated = new ArrayList<>(lines.subList(0, maxLines));
        int last = maxLines - 1;
        truncated.set(last, withEllipsis(truncated.get(last), fm, maxWidth));
        return truncated;
    }

    /**
     * Shortens text with an ellipsis so it fits {@code maxWidth}. Returns the text unchanged if it fits.
     */
    static String ellipsize(String text, FontMetrics fm, int maxWidth) {
        if (text == null) {
            return "";
        }
        if (fm.stringWidth(text) <= maxWidth) {
            return text;
        }
        return withEllipsis(text, fm, maxWidth);
    }

    /**
     * Returns {@code font} if it can draw every character of {@code text}, otherwise a fallback font
     * (RuneScape fonts lack emoji and most non-Latin glyphs).
     */
    static Font displayable(Font font, String text) {
        if (text == null || font.canDisplayUpTo(text) == -1) {
            return font;
        }
        // RuneScape fonts are nominally larger than they look; shrink the fallback to a similar visual size
        return FontManager.getDefaultFont().deriveFont(font.getStyle(), font.getSize2D() * FALLBACK_FONT_SCALE);
    }

    private static String withEllipsis(String text, FontMetrics fm, int maxWidth) {
        String trimmed = text;
        while (!trimmed.isEmpty() && fm.stringWidth(trimmed + ELLIPSIS) > maxWidth) {
            trimmed = trimmed.substring(0, trimmed.length() - 1);
        }
        return trimmed.trim() + ELLIPSIS;
    }

    private static int fittingChars(String word, FontMetrics fm, int maxWidth) {
        int count = 1;
        while (count < word.length() && fm.stringWidth(word.substring(0, count + 1)) <= maxWidth) {
            count++;
        }
        return count;
    }
}

package org.bingoscape.board;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import org.bingoscape.models.Bingo;
import org.bingoscape.models.Goal;
import org.bingoscape.models.GoalTreeNode;
import org.bingoscape.models.ItemGoal;
import org.bingoscape.models.Tile;
import org.bingoscape.models.TileSubmissionType;
import org.bingoscape.services.TileImageCache;
import org.bingoscape.ui.TileStatusStyle;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.IntFunction;

/**
 * Paints the tile details view inside the board's grid area: title, XP, description, goal tree with
 * progress, submission status, header image and the action buttons.
 */
final class TileDetailsView {
    private static final int INSET = 8;
    private static final int BUTTON_HEIGHT = 22;
    private static final int BUTTON_GAP = 6;
    private static final int IMAGE_SIZE = 150;
    private static final int SCROLLBAR_WIDTH = 4;
    private static final int INDENT_PER_LEVEL = 16;
    private static final int ITEM_ICON_SIZE = 16;
    private static final int PROGRESS_BAR_WIDTH = 80;
    private static final int PROGRESS_BAR_HEIGHT = 6;
    private static final Color OR_BADGE_BG = new Color(59, 130, 246, 50);
    private static final Color AND_BADGE_BG = new Color(55, 65, 81, 180);

    /**
     * Click targets and scroll limits produced by a paint, in overlay coordinates.
     */
    static final class DetailsHit {
        final Rectangle primaryButton;
        final Rectangle closeButton;
        final Rectangle scrollArea;
        final boolean primaryEnabled;
        final int maxScroll;

        DetailsHit(Rectangle primaryButton, Rectangle closeButton, Rectangle scrollArea, boolean primaryEnabled, int maxScroll) {
            this.primaryButton = primaryButton;
            this.closeButton = closeButton;
            this.scrollArea = scrollArea;
            this.primaryEnabled = primaryEnabled;
            this.maxScroll = maxScroll;
        }
    }

    private TileDetailsView() {
    }

    static String primaryLabel(Tile tile, Bingo bingo) {
        if (bingo.isLocked()) {
            return "Submissions locked";
        }
        if (TileStatusStyle.statusOf(tile) == TileSubmissionType.ACCEPTED) {
            return "Already Completed";
        }
        return "Take & Review Screenshot";
    }

    static boolean primaryEnabled(Tile tile, Bingo bingo) {
        return !bingo.isLocked() && TileStatusStyle.statusOf(tile) != TileSubmissionType.ACCEPTED;
    }

    /**
     * @param images     image cache, or null when tile images are disabled
     * @param itemImages item id to item sprite (RuneLite ItemManager)
     */
    static DetailsHit paint(Graphics2D g, Rectangle area, Tile tile, Bingo bingo, TileImageCache images,
                            IntFunction<BufferedImage> itemImages, int scrollPx, Point mouse) {
        g.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g.fillRect(area.x, area.y, area.width, area.height);
        g.setColor(ColorScheme.BORDER_COLOR);
        g.drawRect(area.x, area.y, area.width - 1, area.height - 1);

        Rectangle inner = new Rectangle(area.x + INSET, area.y + INSET, area.width - 2 * INSET, area.height - 2 * INSET);

        // Footer buttons
        g.setFont(FontManager.getRunescapeSmallFont());
        FontMetrics buttonFm = g.getFontMetrics();
        String primaryText = primaryLabel(tile, bingo);
        boolean enabled = primaryEnabled(tile, bingo);
        int buttonY = inner.y + inner.height - BUTTON_HEIGHT;
        int primaryWidth = buttonFm.stringWidth(primaryText) + 16;
        Rectangle primary = new Rectangle(inner.x + inner.width - primaryWidth, buttonY, primaryWidth, BUTTON_HEIGHT);
        int closeWidth = buttonFm.stringWidth("Close") + 16;
        Rectangle close = new Rectangle(primary.x - BUTTON_GAP - closeWidth, buttonY, closeWidth, BUTTON_HEIGHT);

        BoardDraw.button(g, close, contains(close, mouse), true);
        BoardDraw.centeredText(g, "Close", close, Color.WHITE);
        BoardDraw.button(g, primary, contains(primary, mouse), enabled);
        BoardDraw.centeredText(g, primaryText, primary, enabled ? Color.WHITE : Color.GRAY);

        // Header image on the right (not scrolled)
        int contentBottom = buttonY - BUTTON_GAP;
        boolean hasImage = images != null && tile.getHeaderImage() != null && !tile.getHeaderImage().trim().isEmpty();
        int imageSize = hasImage ? Math.min(IMAGE_SIZE, Math.min(inner.width / 3, contentBottom - inner.y)) : 0;
        if (imageSize > 0) {
            Rectangle imageBox = new Rectangle(inner.x + inner.width - imageSize, inner.y, imageSize, imageSize);
            paintImage(g, imageBox, tile, images);
        }

        // Scrollable text column on the left
        int columnWidth = inner.width - (imageSize > 0 ? imageSize + INSET : 0);
        Rectangle column = new Rectangle(inner.x, inner.y, Math.max(0, columnWidth), Math.max(0, contentBottom - inner.y));
        int textWidth = column.width - SCROLLBAR_WIDTH - 4;

        Graphics2D cg = (Graphics2D) g.create();
        int contentHeight;
        try {
            cg.clipRect(column.x, column.y, column.width, column.height);
            cg.translate(0, -scrollPx);
            contentHeight = paintContent(cg, column.x, column.y, textWidth, tile, itemImages) - column.y;
        } finally {
            cg.dispose();
        }

        int maxScroll = Math.max(0, contentHeight - column.height);
        if (maxScroll > 0) {
            paintScrollbar(g, column, contentHeight, Math.min(scrollPx, maxScroll));
        }

        return new DetailsHit(primary, close, column, enabled, maxScroll);
    }

    /**
     * Paints the text content starting at {@code y} and returns the y coordinate below the last line.
     */
    private static int paintContent(Graphics2D g, int x, int y, int width, Tile tile, IntFunction<BufferedImage> itemImages) {
        // Title
        g.setFont(FontManager.getRunescapeBoldFont());
        y = paintWrapped(g, tile.getTitle(), x, y, width, Color.WHITE);

        // XP
        g.setFont(FontManager.getRunescapeFont());
        y = paintWrapped(g, "XP: " + tile.getWeight(), x, y + 2, width, Color.LIGHT_GRAY) + 6;

        // Description
        if (tile.getDescription() != null && !tile.getDescription().trim().isEmpty()) {
            y = paintWrapped(g, tile.getDescription(), x, y, width, Color.WHITE) + 6;
        }

        y = paintGoals(g, tile, x, y, width, itemImages);

        // Submission status
        TileSubmissionType status = TileStatusStyle.statusOf(tile);
        if (TileStatusStyle.isSubmitted(status)) {
            g.setFont(FontManager.getRunescapeFont());
            y = paintWrapped(g, "Status: " + TileStatusStyle.displayText(status), x, y, width, TileStatusStyle.accent(status));
            if (tile.getSubmission().getSubmissionCount() > 0) {
                y = paintWrapped(g, "Submissions: " + tile.getSubmission().getSubmissionCount(), x, y + 2, width, Color.LIGHT_GRAY);
            }
        }

        return y;
    }

    /**
     * Paints the "Goals:" heading and the goal tree (or flat goal list) and returns the y below it.
     * Returns {@code y} unchanged when the tile has no goals.
     */
    static int paintGoals(Graphics2D g, Tile tile, int x, int y, int width, IntFunction<BufferedImage> itemImages) {
        // Prefer the hierarchical tree, fall back to the flat goal list
        List<GoalTreeNode> goalTree = tile.getGoalTree();
        List<Goal> goals = tile.getGoals();
        boolean hasTree = goalTree != null && !goalTree.isEmpty();
        if (!hasTree && (goals == null || goals.isEmpty())) {
            return y;
        }

        g.setFont(FontManager.getRunescapeBoldFont());
        y = paintWrapped(g, "Goals:", x, y, width, Color.WHITE) + 2;
        g.setFont(FontManager.getRunescapeSmallFont());
        if (hasTree) {
            for (GoalTreeNode node : goalTree) {
                y = paintNode(g, node, 0, x, y, width, itemImages);
            }
        } else {
            for (Goal goal : goals) {
                y = paintFlatGoal(g, goal, x, y, width);
            }
        }
        return y + 6;
    }

    private static int paintNode(Graphics2D g, GoalTreeNode node, int depth, int x, int y, int width,
                                 IntFunction<BufferedImage> itemImages) {
        if (node == null) {
            return y;
        }

        int indent = Math.min(depth * INDENT_PER_LEVEL, width / 3);
        if (node.isGroup()) {
            String operator = node.getLogicalOperator() != null ? node.getLogicalOperator() : "AND";
            boolean hasName = node.getName() != null && !node.getName().isEmpty();
            String name = hasName ? node.getName() : "Group";
            boolean hasProgress = node.getProgress() != null;
            int completed = hasProgress ? node.getProgress().getCompletedCount() : 0;
            int total = hasProgress ? node.getProgress().getTotalCount() : 0;
            boolean complete = hasProgress && node.getProgress().isComplete();

            y = paintGoalRow(g, x + indent, y, width - indent, operator, null, name, hasName ? BoardDraw.FOREGROUND : BoardDraw.MUTED,
                    hasProgress ? completed + "/" + total : null, completed, total, complete, hasProgress);

            if (node.getChildren() != null) {
                for (GoalTreeNode child : node.getChildren()) {
                    y = paintNode(g, child, depth + 1, x, y, width, itemImages);
                }
            }
            return y;
        }

        if (node.isGoal()) {
            BufferedImage icon = null;
            String name = node.getDescription() != null ? node.getDescription() : "Unknown goal";
            if (node.isItemGoal()) {
                ItemGoal item = node.getItemGoal();
                if (item.getItemId() != null) {
                    icon = itemImages.apply(item.getItemId());
                }
                if (item.getBaseName() != null) {
                    name = item.getExactVariant() != null && !item.getExactVariant().isEmpty()
                            ? item.getBaseName() + " (" + item.getExactVariant() + ")"
                            : item.getBaseName();
                }
            }

            boolean hasProgress = node.getProgress() != null && node.getTargetValue() != null;
            int current = node.getProgress() != null ? node.getProgress().getCompletedCount() : 0;
            int target = node.getTargetValue() != null ? node.getTargetValue() : 1;
            boolean complete = node.getProgress() != null && node.getProgress().isComplete();
            String progressText = hasProgress ? current + "/" + target : "0/1";

            return paintGoalRow(g, x + indent, y, width - indent, null, icon, name, BoardDraw.FOREGROUND,
                    progressText, current, target, complete, node.getProgress() != null);
        }

        return y;
    }

    private static int paintFlatGoal(Graphics2D g, Goal goal, int x, int y, int width) {
        String name = goal.getDescription() != null ? goal.getDescription() : "Unknown goal";
        boolean hasProgress = goal.getProgress() != null;
        int current = hasProgress ? goal.getProgress().getApprovedProgress() : 0;
        boolean complete = hasProgress && goal.getProgress().isCompleted();
        return paintGoalRow(g, x, y, width, null, null, name, BoardDraw.FOREGROUND,
                current + "/" + goal.getTargetValue(), current, goal.getTargetValue(), complete, hasProgress);
    }

    /**
     * One row of the compact goal tree: optional AND/OR badge or item icon, name with a progress bar
     * underneath, and "current/target" on the right.
     */
    private static int paintGoalRow(Graphics2D g, int x, int y, int width, String operator, BufferedImage icon,
                                    String name, Color nameColor, String progressText, int current, int target,
                                    boolean complete, boolean hasProgress) {
        FontMetrics fm = g.getFontMetrics();
        int lineHeight = fm.getHeight();
        int top = y + 2;
        int baseline = top + fm.getAscent();
        int nameX = x;

        if (operator != null) {
            int badgeWidth = fm.stringWidth(operator) + 8;
            Graphics2D bg = (Graphics2D) g.create();
            try {
                bg.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                bg.setColor("OR".equalsIgnoreCase(operator) ? OR_BADGE_BG : AND_BADGE_BG);
                bg.fillRoundRect(x, top, badgeWidth, lineHeight, 4, 4);
            } finally {
                bg.dispose();
            }
            BoardDraw.text(g, operator, x + 4, baseline, BoardDraw.FOREGROUND);
            nameX += badgeWidth + 4;
        } else if (icon != null) {
            g.drawImage(icon, x, top, ITEM_ICON_SIZE, ITEM_ICON_SIZE, null);
            nameX += ITEM_ICON_SIZE + 4;
        }

        int right = x + width;
        if (progressText != null) {
            int progressWidth = fm.stringWidth(progressText);
            BoardDraw.text(g, progressText, right - progressWidth, baseline,
                    BoardDraw.progressTextColor(current, complete, hasProgress));
            right -= progressWidth + 6;
        }

        BoardDraw.text(g, TextWrap.ellipsize(name, fm, Math.max(0, right - nameX)), nameX, baseline, nameColor);

        int bottom = top + Math.max(lineHeight, icon != null ? ITEM_ICON_SIZE : 0);
        if (hasProgress) {
            int barWidth = Math.max(0, Math.min(PROGRESS_BAR_WIDTH, right - nameX));
            BoardDraw.progressBar(g, nameX, bottom + 2, barWidth, PROGRESS_BAR_HEIGHT, current, target, complete);
            bottom += 2 + PROGRESS_BAR_HEIGHT;
        }
        return bottom + 2;
    }

    private static int paintWrapped(Graphics2D g, String text, int x, int y, int width, Color color) {
        Font font = TextWrap.displayable(g.getFont(), text);
        g.setFont(font);
        FontMetrics fm = g.getFontMetrics();
        for (String line : TextWrap.wrap(text, fm, width, Integer.MAX_VALUE)) {
            BoardDraw.text(g, line, x, y + fm.getAscent(), color);
            y += fm.getHeight();
        }
        return y;
    }

    private static void paintImage(Graphics2D g, Rectangle box, Tile tile, TileImageCache images) {
        BufferedImage image = images.getScaled(tile.getHeaderImage(), box.width, box.height);
        if (image == null) {
            image = images.getSource(tile.getHeaderImage());
        }

        if (image != null) {
            Rectangle target = BoardDraw.fitted(image.getWidth(), image.getHeight(), box);
            Graphics2D ig = (Graphics2D) g.create();
            try {
                ig.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                ig.drawImage(image, target.x, target.y, target.width, target.height, null);
            } finally {
                ig.dispose();
            }
            return;
        }

        if (!images.hasFailed(tile.getHeaderImage())) {
            g.setFont(FontManager.getRunescapeSmallFont());
            BoardDraw.centeredText(g, "Loading...", box, Color.LIGHT_GRAY);
        }
    }

    private static void paintScrollbar(Graphics2D g, Rectangle column, int contentHeight, int scrollPx) {
        int trackX = column.x + column.width - SCROLLBAR_WIDTH;
        g.setColor(ColorScheme.DARK_GRAY_COLOR);
        g.fillRect(trackX, column.y, SCROLLBAR_WIDTH, column.height);

        int thumbHeight = Math.max(16, column.height * column.height / contentHeight);
        int maxScroll = contentHeight - column.height;
        int thumbY = column.y + (int) ((long) (column.height - thumbHeight) * scrollPx / Math.max(1, maxScroll));
        g.setColor(ColorScheme.MEDIUM_GRAY_COLOR);
        g.fillRect(trackX, thumbY, SCROLLBAR_WIDTH, thumbHeight);
    }

    private static boolean contains(Rectangle r, Point p) {
        return p != null && r.contains(p);
    }
}

