    private static final int PADDING = 8;
    private static final int ICON_BOX = 40;
    private static final int ROW_GAP = 1;
    private static final int RADIUS = BingoTheme.CORNER_RADIUS;
    private static final Color WARNING = BingoTheme.PROGRESS_PARTIAL;

    private final BingoScapeConfig config;
    private final ItemManager itemManager;
    // Guarded by itself; one FIFO per priority, completions first
    private final Deque<Notification> completionQueue = new ArrayDeque<>();
    private final Deque<Notification> dropQueue = new ArrayDeque<>();

    // Render-thread only
    private Notification current;
    private long startedAt;
    private boolean hurry;
    private int cachedScale = -1;
    private Font regular;
    private Font bold;

    // Text of the current popup fitted to the card; reset when the popup or the scale changes
    private String fittedCaption;
    private String fittedName;
    private String valueText;
    private String fittedTile;
    private String fittedWarning;

    @Inject
    public DropNotificationOverlay(BingoScapeConfig config, ItemManager itemManager) {
        this.config = config;
        this.itemManager = itemManager;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
        setMovable(false);
    }

    /**
     * Queues a popup. When the queue is full, the oldest waiting drop makes room for a completion; a drop
     * that finds no room is discarded.
     */
    public void enqueue(Notification notification) {
        synchronized (this) {
            boolean completion = notification.priority() == Notification.PRIORITY_COMPLETION;
            if (queueSize() >= MAX_QUEUE) {
                if (!completion || dropQueue.isEmpty()) {
                    return;
                }
                dropQueue.pollFirst();
            }
            (completion ? completionQueue : dropQueue).offerLast(notification);
        }
    }

    public synchronized void clear() {
        completionQueue.clear();
        dropQueue.clear();
    }

    synchronized int queueSize() {
        return completionQueue.size() + dropQueue.size();
    }

    /**
     * Next popup to show: completions before drops, first in first out within the same kind.
     */
    synchronized Notification pollNext() {
        Notification next = completionQueue.pollFirst();
        return next != null ? next : dropQueue.pollFirst();
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        long now = System.currentTimeMillis();
        if (current != null && now - startedAt >= totalMs(holdMs(current), hurry)) {
            current = null;
        }
        if (current == null) {
            current = pollNext();
            if (current != null) {
                startedAt = now;
                // Decided once per popup so the fade timing cannot jump when more drops arrive;
                // completions always get their full time
                hurry = current instanceof DropNotification && queueSize() > 0;
                resetFittedText();
            }
        }
        if (current == null) {
            return null;
        }

        applyScale();
        double scale = config.notificationScale() / 100.0;
        int pad = (int) Math.round(PADDING * scale);
        FontMetrics small = graphics.getFontMetrics(regular);
        FontMetrics big = graphics.getFontMetrics(bold);
        Layout layout = Layout.of(small.getHeight(), big.getHeight(), pad,
                current instanceof DropNotification && ((DropNotification) current).getWarning() != null);
        int width = (int) Math.round(BASE_WIDTH * scale);

        long elapsed = now - startedAt;
        float alpha = alpha(elapsed, holdMs(current), hurry);
        int slideOffset = (int) Math.round(-layout.height * (1 - slideProgress(elapsed)));

        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
            // Slide inside the overlay bounds so nothing is drawn above the game view
            g.clipRect(0, 0, width, layout.height);
            g.translate(0, slideOffset);
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
            if (current instanceof TileCompletedNotification) {
                paintCompletion(g, (TileCompletedNotification) current, width, layout, scale, pad);
            } else {
                paintCard(g, (DropNotification) current, width, layout, scale, pad);
            }
        } finally {
            g.dispose();
        }
        return new Dimension(width, layout.height);
    }

    /**
     * Vertical layout derived from the font heights, so the rows never overlap at any scale.
     */
    static final class Layout {
        final int pillHeight;
        final int captionY;
        final int nameY;
        final int statY;
        final int contentBottom;
        final int warningY;
        final int height;

        private Layout(int pillHeight, int captionY, int nameY, int statY, int contentBottom, int warningY, int height) {
            this.pillHeight = pillHeight;
            this.captionY = captionY;
            this.nameY = nameY;
            this.statY = statY;
            this.contentBottom = contentBottom;
            this.warningY = warningY;
            this.height = height;
        }

        static Layout of(int smallHeight, int boldHeight, int pad, boolean warning) {
            int pillHeight = smallHeight + 2;
            int captionY = pad;
            int nameY = captionY + pillHeight + ROW_GAP;
            int statY = nameY + boldHeight;
            int contentBottom = statY + smallHeight + pad;
            int warningHeight = warning ? smallHeight + 4 : 0;
            return new Layout(pillHeight, captionY, nameY, statY, contentBottom, contentBottom, contentBottom + warningHeight);
        }
    }

    private void paintCard(Graphics2D g, DropNotification drop, int width, Layout layout, double scale, int pad) {
        Color accent = drop.getTier().color();
        int arc = (int) Math.round(RADIUS * scale);
        int height = layout.height;

        // Card with a soft tier-colored glow under the border
        g.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g.fillRoundRect(0, 0, width, height, arc, arc);
        g.setColor(BingoTheme.withAlpha(accent, 30));
        g.fillRoundRect(0, 0, width, height, arc, arc);
        g.setStroke(new BasicStroke(3f));
        g.setColor(BingoTheme.withAlpha(accent, 60));
        g.drawRoundRect(1, 1, width - 3, height - 3, arc, arc);
        g.setStroke(new BasicStroke(1.5f));
        g.setColor(accent);
        g.drawRoundRect(1, 1, width - 3, height - 3, arc, arc);

        // Item icon on a tinted square, centered in the content area
        int box = (int) Math.round(ICON_BOX * scale);
        int boxY = Math.max(pad, (layout.contentBottom - box) / 2);
        g.setColor(BingoTheme.withAlpha(accent, 50));
        g.fillRoundRect(pad, boxY, box, box, arc, arc);
        g.setColor(BingoTheme.withAlpha(accent, 140));
        g.setStroke(new BasicStroke(1f));
        g.drawRoundRect(pad, boxY, box - 1, box - 1, arc, arc);
        paintIcon(g, drop, pad, boxY, box, accent);

        int textX = pad + box + pad;
        int textRight = width - pad;

        // Caption row: "Bingo Item" left, tier pill (and +N queued) right
        g.setFont(regular);
        FontMetrics small = g.getFontMetrics();
        String tierLabel = drop.getTier().label();
        int pillWidth = small.stringWidth(tierLabel) + 12;
        int pillX = textRight - pillWidth;
        g.setColor(BingoTheme.withAlpha(accent, 50));
        g.fillRoundRect(pillX, layout.captionY, pillWidth - 1, layout.pillHeight - 1, layout.pillHeight, layout.pillHeight);
        g.setColor(BingoTheme.withAlpha(accent, 140));
        g.drawRoundRect(pillX, layout.captionY, pillWidth - 1, layout.pillHeight - 1, layout.pillHeight, layout.pillHeight);
        shadowed(g, tierLabel, pillX + 6, layout.captionY + 1 + small.getAscent(), accent);

        int captionRight = pillX - 4;
        int queued = queueSize();
        if (queued > 0) {
            String more = "+" + queued;
            captionRight -= small.stringWidth(more) + 4;
            shadowed(g, more, pillX - 4 - small.stringWidth(more), layout.captionY + small.getAscent(), BingoTheme.MUTED);
        }
        if (fittedCaption == null) {
            fittedCaption = ellipsize(caption(drop), small, captionRight - textX);
        }
        shadowed(g, fittedCaption, textX, layout.captionY + small.getAscent(), BingoTheme.MUTED);

        // Item name in the tier color
        g.setFont(bold);
        FontMetrics big = g.getFontMetrics();
        if (fittedName == null) {
            String name = (drop.getQuantity() > 1 ? drop.getQuantity() + " x " : "") + drop.getItemName();
            fittedName = ellipsize(name, big, textRight - textX);
        }
        shadowed(g, fittedName, textX, layout.nameY + big.getAscent(), accent);

        // Value left, tile right
        g.setFont(regular);
        if (valueText == null) {
            valueText = drop.getStackValue() > 0 ? DropTierResolver.formatGp(drop.getStackValue()) + " gp" : "No value";
            if (drop.getTileTitle() != null) {
                String tile = drop.getTileTitle() + (drop.getExtraTiles() > 0 ? " +" + drop.getExtraTiles() : "");
                fittedTile = ellipsize(tile, small, textRight - (textX + small.stringWidth(valueText) + pad));
            }
        }
        shadowed(g, valueText, textX, layout.statY + small.getAscent(), Color.WHITE);
        if (fittedTile != null) {
            shadowed(g, fittedTile, textRight - small.stringWidth(fittedTile), layout.statY + small.getAscent(), BingoTheme.MUTED);
        }

        if (drop.getWarning() != null) {
            if (fittedWarning == null) {
                fittedWarning = ellipsize(drop.getWarning(), small, width - 2 * pad);
            }
            g.setColor(BingoTheme.withAlpha(WARNING, 40));
            g.fillRect(2, layout.warningY, width - 4, height - layout.warningY - 2);
            int textY = layout.warningY + (height - 2 - layout.warningY - small.getHeight()) / 2 + small.getAscent();
            shadowed(g, fittedWarning, pad, textY, WARNING);
        }
    }

    private void paintCompletion(Graphics2D g, TileCompletedNotification done, int width, Layout layout, double scale, int pad) {
        int arc = (int) Math.round(RADIUS * scale);
        int height = layout.height;

        g.setColor(ColorScheme.DARKER_GRAY_COLOR);
        g.fillRoundRect(0, 0, width, height, arc, arc);
        g.setColor(BingoTheme.withAlpha(GREEN, 30));
        g.fillRoundRect(0, 0, width, height, arc, arc);
        g.setStroke(new BasicStroke(3f));
        g.setColor(BingoTheme.withAlpha(GOLD, 60));
        g.drawRoundRect(1, 1, width - 3, height - 3, arc, arc);
        g.setStroke(new BasicStroke(1.5f));
        g.setColor(GOLD);
        g.drawRoundRect(1, 1, width - 3, height - 3, arc, arc);

        // Checkmark on a tinted square, centered in the content area
        int box = (int) Math.round(ICON_BOX * scale);
        int boxY = Math.max(pad, (layout.contentBottom - box) / 2);
        g.setColor(BingoTheme.withAlpha(GREEN, 50));
        g.fillRoundRect(pad, boxY, box, box, arc, arc);
        g.setColor(BingoTheme.withAlpha(GREEN, 140));
        g.setStroke(new BasicStroke(1f));
        g.drawRoundRect(pad, boxY, box - 1, box - 1, arc, arc);
        g.setStroke(new BasicStroke(Math.max(2f, (float) (3 * scale)), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(GREEN);
        int[] xs = {pad + box * 22 / 100, pad + box * 43 / 100, pad + box * 78 / 100};
        int[] ys = {boxY + box * 53 / 100, boxY + box * 72 / 100, boxY + box * 30 / 100};
        g.drawPolyline(xs, ys, 3);

        int textX = pad + box + pad;
        int textRight = width - pad;

        g.setFont(regular);
        FontMetrics small = g.getFontMetrics();
        int captionRight = textRight;
        int queued = queueSize();
        if (queued > 0) {
            String more = "+" + queued;
            captionRight -= small.stringWidth(more);
            shadowed(g, more, textRight - small.stringWidth(more), layout.captionY + small.getAscent(), BingoTheme.MUTED);
        }
        if (fittedCaption == null) {
            fittedCaption = ellipsize("Tile Completed", small, captionRight - textX);
        }
        shadowed(g, fittedCaption, textX, layout.captionY + small.getAscent(), GREEN);

        g.setFont(bold);
        FontMetrics big = g.getFontMetrics();
        if (fittedName == null) {
            fittedName = ellipsize(done.getTileTitle(), big, textRight - textX);
        }
        shadowed(g, fittedName, textX, layout.nameY + big.getAscent(), GOLD);

        g.setFont(regular);
        if (valueText == null) {
            valueText = done.getPoints() > 0 ? "+" + done.getPoints() + " pts" : "";
            if (done.getTeamName() != null && !done.getTeamName().trim().isEmpty()) {
                fittedTile = ellipsize(done.getTeamName().trim(), small, textRight - (textX + small.stringWidth(valueText) + pad));
            }
        }
        shadowed(g, valueText, textX, layout.statY + small.getAscent(), Color.WHITE);
        if (fittedTile != null) {
            shadowed(g, fittedTile, textRight - small.stringWidth(fittedTile), layout.statY + small.getAscent(), BingoTheme.MUTED);
        }
    }

    private void paintIcon(Graphics2D g, DropNotification drop, int x, int y, int box, Color accent) {
        // The stack size is part of the name ("N x ..."), so no count on the sprite
        BufferedImage icon = itemManager.getImage(drop.getItemId(), drop.getQuantity(), false);
        if (icon == null) {
            // Sprite not loaded: first letter on the tinted square
            g.setFont(bold);
            String letter = drop.getItemName().isEmpty() ? "?" : drop.getItemName().substring(0, 1).toUpperCase();
            FontMetrics fm = g.getFontMetrics();
            shadowed(g, letter, x + (box - fm.stringWidth(letter)) / 2,
                    y + (box - fm.getHeight()) / 2 + fm.getAscent(), accent);
            return;
        }

        // Fit the sprite into the box, keep it crisp
        double ratio = Math.min((box - 4.0) / icon.getWidth(), (box - 4.0) / icon.getHeight());
        int w = Math.max(1, (int) Math.round(icon.getWidth() * ratio));
        int h = Math.max(1, (int) Math.round(icon.getHeight() * ratio));
        Object previous = g.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(icon, x + (box - w) / 2, y + (box - h) / 2, w, h, null);
        if (previous != null) {
            g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, previous);
        }
    }

    private void applyScale() {
        int scale = config.notificationScale();
        if (scale == cachedScale) {
            return;
        }
        cachedScale = scale;
        Font small = FontManager.getRunescapeSmallFont();
        Font large = FontManager.getRunescapeBoldFont();
        regular = small.deriveFont(small.getSize2D() * scale / 100f);
        bold = large.deriveFont(large.getSize2D() * scale / 100f);
        resetFittedText();
    }

    private void resetFittedText() {
        fittedCaption = null;
        fittedName = null;
        valueText = null;
        fittedTile = null;
        fittedWarning = null;
    }

    /**
     * Caption of the card: who received the drop for team drops, else the generic label.
     */
    static String caption(DropNotification drop) {
        String player = drop.getPlayerName();
        return player == null || player.trim().isEmpty() ? "Bingo Item" : player.trim() + " received";
    }

    private long holdMs(Notification notification) {
        return holdFor(notification, config.notificationSeconds() * 1000L);
    }

    /**
     * Hold time of a popup: completions stay 1.5 times as long as drops.
     */
    static long holdFor(Notification notification, long baseMs) {
        return notification instanceof TileCompletedNotification ? Math.round(baseMs * COMPLETION_HOLD_FACTOR) : baseMs;
    }

    private static void shadowed(Graphics2D g, String text, int x, int baseline, Color color) {
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, baseline + 1);
        g.setColor(color);
        g.drawString(text, x, baseline);
    }

    private static String ellipsize(String text, FontMetrics fm, int maxWidth) {
        if (fm.stringWidth(text) <= maxWidth) {
            return text;
        }
        String ellipsis = "...";
        int end = text.length();
        while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > maxWidth) {
            end--;
        }
        return text.substring(0, end) + ellipsis;
    }

    /**
     * Visible time of one popup: slide in, hold, fade out. The hold shrinks when more popups wait.
     */
    static long totalMs(long holdMs, boolean hurry) {
        return SLIDE_MS + effectiveHold(holdMs, hurry) + FADE_MS;
    }

    private static long effectiveHold(long holdMs, boolean hurry) {
        return hurry ? Math.round(holdMs * QUEUED_HOLD_FACTOR) : holdMs;
    }

    /**
     * Overall opacity at {@code elapsedMs}: fades in with the slide, full during the hold, fades out at the end.
     */
    static float alpha(long elapsedMs, long holdMs, boolean hurry) {
        long fadeStart = SLIDE_MS + effectiveHold(holdMs, hurry);
        if (elapsedMs < SLIDE_MS) {
            return clamp(elapsedMs / (float) SLIDE_MS);
        }
        if (elapsedMs < fadeStart) {
            return 1f;
        }
        return clamp(1f - (elapsedMs - fadeStart) / (float) FADE_MS);
    }

    /**
     * Ease-out-cubic slide progress, 0 at start and 1 once the popup has arrived.
     */
    static float slideProgress(long elapsedMs) {
        float t = clamp(elapsedMs / (float) SLIDE_MS);
        return 1f - (1f - t) * (1f - t) * (1f - t);
    }

    private static float clamp(float value) {
        return Math.max(0f, Math.min(1f, value));
    }
}

package org.bingoscape.notifications;

import org.bingoscape.ui.BingoTheme;
import org.bingoscape.ui.TileStatusStyle;

import java.awt.Color;

/**
 * Value tier of a drop. Decides the accent color of the drop popup.
 */
public enum DropTier {
    COMMON("Common", new Color(200, 200, 200)),
    UNCOMMON("Uncommon", BingoTheme.PROGRESS_COMPLETE),
    RARE("Rare", TileStatusStyle.PENDING),
    EPIC("Epic", new Color(168, 85, 247)),
    LEGENDARY("Legendary", BingoTheme.GOLD);

    private final String label;
    private final Color color;

    DropTier(String label, Color color) {
        this.label = label;
        this.color = color;
    }

    public String label() {
        return label;
    }

    public Color color() {
        return color;
    }
}

package org.bingoscape.notifications;

import java.util.Arrays;

/**
 * Maps the GE value of a drop to a {@link DropTier}, and formats gp amounts for the popup.
 */
public final class DropTierResolver {
    private DropTierResolver() {
    }

    /**
     * A value at or above a threshold falls into that threshold's tier. Thresholds are sorted first,
     * so a misconfigured order still gives monotonic tiers.
     */
    public static DropTier resolve(long stackValue, long uncommon, long rare, long epic, long legendary) {
        long[] thresholds = {uncommon, rare, epic, legendary};
        Arrays.sort(thresholds);

        DropTier[] tiers = DropTier.values();
        DropTier result = DropTier.COMMON;
        for (int i = 0; i < thresholds.length; i++) {
            if (stackValue >= Math.max(1, thresholds[i])) {
                result = tiers[i + 1];
            }
        }
        return result;
    }

    /**
     * Formats a gp amount the way the game does: 950, 12.5k, 3.2m, 1.1b.
     */
    public static String formatGp(long value) {
        if (value < 10_000) {
            return String.valueOf(value);
        }
        if (value < 1_000_000) {
            return trim(value / 1_000.0) + "k";
        }
        if (value < 1_000_000_000L) {
            return trim(value / 1_000_000.0) + "m";
        }
        return trim(value / 1_000_000_000.0) + "b";
    }

    private static String trim(double scaled) {
        // One decimal below 100, none above; no trailing ".0"
        if (scaled >= 100) {
            return String.valueOf(Math.round(scaled));
        }
        double rounded = Math.round(scaled * 10) / 10.0;
        return rounded == Math.floor(rounded) ? String.valueOf((long) rounded) : String.valueOf(rounded);
    }
}

package org.bingoscape.notifications;

/**
 * A popup the overlay can show. Lower priority values are shown first.
 */
public interface Notification {
    int PRIORITY_COMPLETION = 0;
    int PRIORITY_DROP = 1;

    int priority();
}

package org.bingoscape.notifications;

import lombok.Value;

/**
 * Popup for a bingo tile the team has completed.
 */
@Value
public class TileCompletedNotification implements Notification {
    String tileTitle;
    int points;
    String teamName;

    @Override
    public int priority() {
        return PRIORITY_COMPLETION;
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.models.AutoSubmissionMetadata;
import org.bingoscape.models.Tile;
import org.bingoscape.notifications.DropNotification;
import org.bingoscape.notifications.DropNotificationOverlay;
import org.bingoscape.notifications.DropTier;
import org.bingoscape.notifications.DropTierResolver;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Handles automatic tile submissions when game events match tile requirements.
 * Monitors loot events and triggers screenshot + submission when items are
 * obtained.
 */
@Slf4j
@Singleton
public class AutoSubmissionHandler {
    // Track recently submitted tiles to avoid duplicates within a short time window
    private final Map<UUID, Long> recentSubmissions = new ConcurrentHashMap<>();
    private static final long SUBMISSION_COOLDOWN_MS = 5000; // 5 seconds

    @Inject
    private BingoScapePlugin plugin;

    @Inject
    private BingoScapeConfig config;

    @Inject
    private TileRequirementMatcher requirementMatcher;

    @Inject
    private DropNotificationOverlay dropOverlay;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    /**
     * Handles NPC loot received events (most common source of item drops).
     */
    public void onNpcLootReceived(NpcLootReceived event) {
        if (!shouldProcessEvent()) {
            return;
        }

        NPC npc = event.getNpc();
        int npcId = npc.getId();
        String npcName = npc.getName();

        Collection<ItemStack> items = event.getItems();
        processItemDrops(items, npcId, npcName, "NPC loot");
    }

    /**
     * Handles generic loot received events (pickpocket, event rewards, etc.).
     */
    public void onLootReceived(LootReceived event) {
        if (!shouldProcessEvent()) {
            return;
        }

        // Only process non-NPC loot (NPC loot is handled by onNpcLootReceived)
        if (event.getType() == LootRecordType.NPC) {
            return;
        }

        // For non-NPC loot, we don't have an NPC ID
        Collection<ItemStack> items = event.getItems();
        processItemDrops(items, null, event.getName(), event.getType().name());
    }

    /**
     * Gets the current logged-in RuneScape account name.
     * Uses the plugin's client to get the local player name.
     */
    private String getAccountName() {
        try {
            return plugin.getAccountName();
        } catch (Exception e) {
            log.warn("Failed to get account name", e);
            return null;
        }
    }

    /**
     * Processes a collection of item drops to check if any match tile requirements.
     */
    private void processItemDrops(Collection<ItemStack> items, Integer npcId, String sourceName, String sourceType) {
        if (items == null || items.isEmpty()) {
            return;
        }

        log.debug("Processing {} items from {} ({})", items.size(), sourceName, sourceType);

        for (ItemStack item : items) {
            int itemId = item.getId();
            int quantity = item.getQuantity();

            // Check if this item is required for any tile
            if (requirementMatcher.isRequiredItem(itemId, npcId)) {
                log.info("Found required item {} from {}", itemId, sourceName);

                // Get all tiles that can be completed with this item
                List<UUID> matchingTiles = requirementMatcher.getTilesForItem(itemId, npcId);
                if (matchingTiles.isEmpty()) {
                    continue;
                }
                String warning = notSubmittedReason();

                // One popup per drop, shown immediately when the item is obtained
                showDropNotification(itemId, quantity, matchingTiles, warning);

                if (warning != null) {
                    continue;
                }

                for (UUID tileId : matchingTiles) {
                    // Check cooldown to avoid duplicate submissions
                    if (isOnCooldown(tileId)) {
                        log.debug("Tile {} is on submission cooldown, skipping", tileId);
                        continue;
                    }
                    submitTileAutomaticWithMetadata(tileId, itemId, quantity, sourceName, npcId, sourceType);
                }
            }
        }
    }

    /**
     * Automatically submits a tile with a screenshot and full metadata.
     */
    private void submitTileAutomaticWithMetadata(UUID tileId, int itemId, int quantity, String sourceName, Integer npcId,
            String sourceType) {
        log.info("Auto-submitting tile {} for item {} from {}", tileId, itemId, sourceName);

        // Mark this tile as recently submitted
        recentSubmissions.put(tileId, System.currentTimeMillis());

        // Get item name NOW (on client thread) before entering background thread
        // This must be done here because ItemManager requires the client thread
        final String itemName = getItemName(itemId);

        // Capture location data (must be on client thread like getItemName)
        int worldX = 0;
        int worldY = 0;
        int plane = 0;
        int worldNumber = 0;
        int regionId = 0;

        try {
            if (client.getLocalPlayer() != null) {
                WorldPoint location = client.getLocalPlayer().getWorldLocation();
                if (location != null) {
                    worldX = location.getX();
                    worldY = location.getY();
                    plane = location.getPlane();
                    regionId = ((worldX >> 6) << 8) | (worldY >> 6);
                }
            }
            worldNumber = client.getWorld();
        } catch (Exception e) {
            log.debug("Failed to capture location metadata", e);
        }

        // Build metadata
        AutoSubmissionMetadata metadata = AutoSubmissionMetadata.builder()
                .itemId(itemId)
                .quantity(quantity)
                .sourceName(sourceName)
                .npcId(npcId)
                .sourceType(sourceType)
                .accountName(getAccountName())
                .worldX(worldX)
                .worldY(worldY)
                .plane(plane)
                .worldNumber(worldNumber)
                .regionId(regionId)
                .build();

        // Take screenshot and submit with metadata
        plugin.takeScreenshot(tileId, screenshotBytes -> {
            if (screenshotBytes == null) {
                log.error("Failed to capture screenshot for tile {}", tileId);
                showChatMessage("Auto-submission failed: could not capture screenshot");
                return;
            }

            // Submit to API with metadata
            plugin.submitTileAutomaticWithMetadata(tileId, screenshotBytes, metadata);

            // Log success in chatbox (use pre-fetched item name from client thread)
            if (config.showAutoSubmitNotifications()) {
                showChatMessage(String.format("Tile auto-submitted for %s", itemName));
            }
        });
    }

    /**
     * Checks if a tile is currently on submission cooldown.
     */
    private boolean isOnCooldown(UUID tileId) {
        Long lastSubmission = recentSubmissions.get(tileId);
        if (lastSubmission == null) {
            return false;
        }

        long elapsed = System.currentTimeMillis() - lastSubmission;
        if (elapsed > SUBMISSION_COOLDOWN_MS) {
            // Cooldown expired, remove from map
            recentSubmissions.remove(tileId);
            return false;
        }

        return true;
    }

    /**
     * Checks if loot events should be matched against tiles at all. This is independent of auto-submission:
     * drops of bingo items are announced even when they are not submitted automatically.
     */
    private boolean shouldProcessEvent() {
        // Check if we have a current bingo loaded
        if (plugin.getCurrentBingo() == null) {
            log.debug("No current bingo loaded");
            return false;
        }

        // Check if the requirement matcher has any trackable tiles
        if (!requirementMatcher.hasTrackableTiles()) {
            log.warn("Requirement matcher has no trackable tiles. Stats: {}", requirementMatcher.getStats());
            return false;
        }

        log.debug("Event processing enabled. Trackable tiles: {}", requirementMatcher.getStats());
        return true;
    }

    /**
     * Returns why matching drops are not submitted automatically (shown on the popup), or null when they are.
     */
    private String notSubmittedReason() {
        if (!config.enableAutoSubmission()) {
            return "Not auto-submitted - submit manually";
        }
        // The server rejects submissions for locked bingos; don't take screenshots for nothing
        if (plugin.getCurrentBingo().isLocked()) {
            return "Bingo is locked - not submitted";
        }
        return null;
    }

    /**
     * Shows the drop popup. Must run on the client thread (item prices and names).
     */
    private void showDropNotification(int itemId, int quantity, List<UUID> tileIds, String warning) {
        if (!config.showAutoSubmitNotifications() || !config.showToastNotifications()) {
            return;
        }

        long stackValue = getItemPrice(itemId) * (long) quantity;
        DropTier tier = DropTierResolver.resolve(stackValue, config.dropUncommonValue(), config.dropRareValue(),
                config.dropEpicValue(), config.dropLegendaryValue());
        String itemName = getItemName(itemId);

        dropOverlay.enqueue(new DropNotification(itemId, itemName, quantity, stackValue, tier,
                getTileTitle(tileIds.get(0)), tileIds.size() - 1, warning));
        log.info("Bingo item drop: {} x{} ({} gp, {})", itemName, quantity, stackValue, tier);
    }

    private String getTileTitle(UUID tileId) {
        if (plugin.getCurrentBingo() == null || plugin.getCurrentBingo().getTiles() == null) {
            return null;
        }
        for (Tile tile : plugin.getCurrentBingo().getTiles()) {
            if (tileId.equals(tile.getId())) {
                return tile.getTitle();
            }
        }
        return null;
    }

    /**
     * GE price of an item, falling back to the high alchemy value for untradeables.
     */
    private long getItemPrice(int itemId) {
        try {
            long price = plugin.getItemManager().getItemPrice(itemId);
            if (price > 0) {
                return price;
            }
            return Math.max(0, plugin.getItemManager().getItemComposition(itemId).getHaPrice());
        } catch (Exception e) {
            log.debug("Failed to get item price for ID {}", itemId, e);
            return 0;
        }
    }

    /**
     * Shows a message in the game chatbox.
     */
    private void showChatMessage(String message) {
        clientThread.invokeLater(
                () -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "BingoScape: " + message, null));
        log.info("Auto-submission chat message: {}", message);
    }

    /**
     * Gets the display name for an item ID.
     */
    private String getItemName(int itemId) {
        try {
            return plugin.getItemManager().getItemComposition(itemId).getName();
        } catch (Exception e) {
            log.warn("Failed to get item name for ID {}", itemId, e);
            return "Item #" + itemId;
        }
    }

    /**
     * Cleans up old cooldown entries to prevent memory leaks.
     */
    public void cleanupCooldowns() {
        long now = System.currentTimeMillis();
        recentSubmissions.entrySet().removeIf(entry -> now - entry.getValue() > SUBMISSION_COOLDOWN_MS);
    }

    /**
     * Gets statistics about auto-submission for debugging.
     */
    public String getStats() {
        return String.format("Auto-submission: enabled=%s, tiles tracked=%s, recent submissions=%d",
                config.enableAutoSubmission(),
                requirementMatcher.hasTrackableTiles(),
                recentSubmissions.size());
    }
}

package org.bingoscape.services;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.models.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;
import java.util.function.Consumer;

@Slf4j
@Singleton
public class BingoScapeApiService {
    private static final MediaType MEDIA_TYPE_PNG = MediaType.parse("image/png");
    private static final MediaType MEDIA_TYPE_JSON = MediaType.parse("application/json");

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final BingoScapeConfig config;

    @Inject
    public BingoScapeApiService(OkHttpClient httpClient, Gson gson, BingoScapeConfig config) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;
    }

    public void fetchActiveEvents(Consumer<List<EventData>> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/events";
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to fetch events", e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to fetch events: " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response: " + response;
                        log.error(error);
                        onError.accept(new ApiError(response.code(), error));
                        return;
                    }

                    String jsonData = responseBody.string();
                    EventData[] eventsResponse = gson.fromJson(jsonData, EventData[].class);
                    onSuccess.accept(Arrays.asList(eventsResponse));
                }
            }
        });
    }

    /**
     * Polls the team drop feed. A null cursor asks for the head cursor only (no backfill).
     * Errors carry the HTTP status and the Retry-After header (429).
     */
    public void fetchTeamDrops(String cursor, int limit, Consumer<TeamDropsResponse> onSuccess, Consumer<ApiError> onError) {
        fetchFeed("/api/runelite/team-drops", "team drops", cursor, limit, TeamDropsResponse.class, onSuccess, onError);
    }

    /**
     * Polls the team tile completion feed, same contract as {@link #fetchTeamDrops}.
     */
    public void fetchTeamCompletions(String cursor, int limit, Consumer<TeamCompletionsResponse> onSuccess, Consumer<ApiError> onError) {
        fetchFeed("/api/runelite/team-tile-completions", "team completions", cursor, limit, TeamCompletionsResponse.class, onSuccess, onError);
    }

    private <T> void fetchFeed(String path, String label, String cursor, int limit, Class<T> type,
                               Consumer<T> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        HttpUrl base = HttpUrl.parse(config.apiBaseUrl() + path);
        if (base == null) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "Invalid API base URL"));
            return;
        }
        HttpUrl.Builder url = base.newBuilder().addQueryParameter("limit", String.valueOf(limit));
        if (cursor != null) {
            url.addQueryParameter("since", cursor);
        }
        Request request = new Request.Builder()
                .url(url.build())
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.debug("Failed to fetch {}", label, e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to fetch " + label + ": " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        onError.accept(new ApiError(response.code(), "Unsuccessful response: " + response,
                                parseRetryAfter(response.header("Retry-After"))));
                        return;
                    }

                    T parsed;
                    try {
                        parsed = gson.fromJson(responseBody.string(), type);
                    } catch (RuntimeException e) {
                        onError.accept(new ApiError(response.code(), "Invalid " + label + " response: " + e.getMessage()));
                        return;
                    }
                    if (parsed == null) {
                        onError.accept(new ApiError(response.code(), "Empty " + label + " response"));
                        return;
                    }
                    onSuccess.accept(parsed);
                }
            }
        });
    }

    static long parseRetryAfter(String header) {
        if (header == null) {
            return -1;
        }
        try {
            return Math.max(0, Long.parseLong(header.trim()));
        } catch (NumberFormatException e) {
            return -1; // HTTP-date form is not supported
        }
    }

    public void refreshBingoBoard(UUID bingoId, Consumer<Bingo> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/bingos/" + bingoId;
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to refresh bingo board", e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to refresh bingo board: " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response when refreshing bingo: " + response;
                        log.error(error);
                        onError.accept(new ApiError(response.code(), error));
                        return;
                    }

                    String jsonData = responseBody.string();
                    Bingo updatedBingo = gson.fromJson(jsonData, Bingo.class);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    public void submitTileCompletion(UUID tileId, byte[] screenshotBytes, Consumer<Bingo> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/tiles/" + tileId + "/submissions";
        RequestBody requestBody = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("image", "screenshot.png", RequestBody.create(MEDIA_TYPE_PNG, screenshotBytes))
                .build();

        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .post(requestBody)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to submit tile completion", e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to submit tile completion: " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    String stringBody = responseBody.string();
                    if (!response.isSuccessful()) {
                        try {
                            ErrorResponse errorResponse = gson.fromJson(stringBody, ErrorResponse.class);
                            String error = errorResponse.getError();
                            log.error("Unsuccessful submission response: {}", error);
                            onError.accept(new ApiError(response.code(), error));
                        } catch (com.google.gson.JsonSyntaxException e) {
                            String error = "HTTP " + response.code() + " Error (Response is not JSON). Raw response: " + stringBody;
                            log.error("Unsuccessful submission response: {}", error);
                            onError.accept(new ApiError(response.code(), error));
                        }
                        return;
                    }

                    Bingo updatedBingo = gson.fromJson(stringBody, Bingo.class);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    /**
     * Submits a tile completion automatically with metadata about the source.
     * This uses a dedicated auto-submission endpoint that can automatically assign goals
     * and approve submissions based on the provided metadata.
     */
    public void submitTileAutomatic(UUID tileId, byte[] screenshotBytes, AutoSubmissionMetadata metadata,
                                     Consumer<Bingo> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/tiles/" + tileId + "/auto-submissions";

        // Convert metadata to JSON
        String metadataJson = gson.toJson(metadata);

        RequestBody requestBody = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("image", "screenshot.png", RequestBody.create(MEDIA_TYPE_PNG, screenshotBytes))
                .addFormDataPart("metadata", metadataJson)
                .build();

        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .post(requestBody)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to submit automatic tile completion", e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to submit automatic tile completion: " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    String stringBody = responseBody.string();
                    if (!response.isSuccessful()) {
                        try {
                            ErrorResponse errorResponse = gson.fromJson(stringBody, ErrorResponse.class);
                            String error = errorResponse.getError();
                            log.error("Unsuccessful auto-submission response: {}", error);
                            onError.accept(new ApiError(response.code(), error));
                        } catch (com.google.gson.JsonSyntaxException e) {
                            String error = "HTTP " + response.code() + " Error (Response is not JSON). Raw response: " + stringBody;
                            log.error("Unsuccessful auto-submission response: {}", error);
                            onError.accept(new ApiError(response.code(), error));
                        }
                        return;
                    }

                    Bingo updatedBingo = gson.fromJson(stringBody, Bingo.class);
                    log.info("Auto-submission successful for tile {}", tileId);
                    onSuccess.accept(updatedBingo);
                }
            }
        });
    }

    public void fetchEvents(Consumer<List<EventData>> onSuccess, Consumer<ApiError> onError) {
        if (!hasApiKey()) {
            onError.accept(new ApiError(ApiError.NO_RESPONSE, "No API key configured"));
            return;
        }

        String apiUrl = config.apiBaseUrl() + "/api/runelite/events";
        Request request = new Request.Builder()
                .url(apiUrl)
                .header("Authorization", "Bearer " + config.apiKey())
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.error("Failed to fetch events", e);
                onError.accept(new ApiError(ApiError.NO_RESPONSE, "Failed to fetch events: " + e.getMessage()));
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (ResponseBody responseBody = response.body()) {
                    if (!response.isSuccessful() || responseBody == null) {
                        String error = "Unsuccessful response when fetching events: " + response;
                        log.error(error);
                        onError.accept(new ApiError(response.code(), error));
                        return;
                    }

                    String jsonData = responseBody.string();
                    EventData[] events = gson.fromJson(jsonData, EventData[].class);
                    onSuccess.accept(Arrays.asList(events));
                }
            }
        });
    }

    private boolean hasApiKey() {
        return config.apiKey() != null && !config.apiKey().isEmpty();
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.SoundEffectID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import org.bingoscape.BingoScapeConfig;
import org.bingoscape.models.ApiError;
import org.bingoscape.models.TeamCompletionsResponse;
import org.bingoscape.models.TeamDropsResponse;
import org.bingoscape.notifications.DropNotification;
import org.bingoscape.notifications.DropNotificationOverlay;
import org.bingoscape.notifications.DropTier;
import org.bingoscape.notifications.DropTierResolver;
import org.bingoscape.notifications.TileCompletedNotification;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

/**
 * Polls the team drop feed and the team tile completion feed and shows a popup for each new drop of a
 * teammate and each tile the team completes. Reschedules itself after
 * every response, so requests never overlap. The first poll after a start only fetches the head cursor,
 * which means drops from before the start are never replayed.
 */
@Slf4j
@Singleton
public class TeamDropPoller {
    static final int PAGE_LIMIT = 50;
    static final int MAX_POPUPS_PER_POLL = 5;
    static final long DEFAULT_INTERVAL_MS = 10_000;
    static final long MIN_INTERVAL_MS = 5_000;
    static final long MAX_BACKOFF_MS = 120_000;
    static final int MAX_COMPLETIONS_PER_POLL = 3;
    static final int MAX_SEEN = 500;
    private static final double JITTER = 0.2;

    private final BingoScapeApiService apiService;
    private final BingoScapeConfig config;
    private final ScheduledExecutorService executor;
    private final ClientThread clientThread;
    private final Client client;
    private final ItemManager itemManager;
    private final DropNotificationOverlay overlay;
    private final Random random = new Random();

    private final Set<String> seen = Collections.newSetFromMap(Collections.synchronizedMap(
            new LinkedHashMap<String, Boolean>() {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest) {
                    return size() > MAX_SEEN;
                }
            }));

    private final Set<String> seenCompletions = Collections.newSetFromMap(Collections.synchronizedMap(
            new LinkedHashMap<String, Boolean>() {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest) {
                    return size() > MAX_SEEN;
                }
            }));

    private volatile String cursor;
    private volatile String completionCursor;
    private volatile boolean running;
    private volatile boolean authBlocked;
    /** Bumped on every start/stop/reset so responses of an older request are dropped. */
    private volatile int generation;
    private volatile ScheduledFuture<?> scheduled;
    private volatile Supplier<String> accountName = () -> null;
    private volatile Supplier<String> currentBingoId = () -> null;
    private volatile Runnable boardRefresh = () -> { };
    private int failures;

    @Inject
    public TeamDropPoller(BingoScapeApiService apiService, BingoScapeConfig config, ScheduledExecutorService executor,
                          ClientThread clientThread, Client client, ItemManager itemManager, DropNotificationOverlay overlay) {
        this.apiService = apiService;
        this.config = config;
        this.executor = executor;
        this.clientThread = clientThread;
        this.client = client;
        this.itemManager = itemManager;
        this.overlay = overlay;
    }

    // ---- Lifecycle ----

    /**
     * Sets how the poller learns the shown bingo and how it asks for a board reload when a tile of that
     * bingo was completed. The callback may run on any thread.
     */
    public void configureBoardRefresh(Supplier<String> currentBingoId, Runnable boardRefresh) {
        this.currentBingoId = currentBingoId;
        this.boardRefresh = boardRefresh;
    }

    /**
     * Starts polling when the feature is enabled and an API key is set; a no-op while already running.
     */
    public synchronized void start(Supplier<String> accountName) {
        this.accountName = accountName;
        if (running || !isEnabled()) {
            return;
        }
        running = true;
        generation++;
        schedule(0, generation);
    }

    /**
     * Stops polling and forgets the cursor, so the next start re-baselines instead of replaying.
     */
    public synchronized void stop() {
        running = false;
        generation++;
        cancelScheduled();
        resetState();
    }

    /**
     * Stop, forget a 401/403 block and start again. For API key or toggle changes.
     */
    public synchronized void restart() {
        stop();
        authBlocked = false;
        start(accountName);
    }

    /**
     * Drops cursor and seen ids (bingo, team or event changed) and polls again right away.
     */
    public synchronized void rebaseline() {
        generation++;
        cancelScheduled();
        resetState();
        if (running && !authBlocked) {
            schedule(0, generation);
        }
    }

    private void resetState() {
        resetDrops();
        resetCompletions();
        failures = 0;
    }

    private void resetDrops() {
        cursor = null;
        seen.clear();
    }

    private void resetCompletions() {
        completionCursor = null;
        seenCompletions.clear();
    }

    private void cancelScheduled() {
        ScheduledFuture<?> future = scheduled;
        if (future != null) {
            future.cancel(false);
        }
    }

    /**
     * True when the popup is on, at least one of the two feeds is wanted and an API key is set.
     */
    public boolean isEnabled() {
        return config.showToastNotifications()
                && (config.showTeamDropNotifications() || config.showTileCompletedNotifications())
                && config.apiKey() != null && !config.apiKey().isEmpty();
    }

    // ---- Polling ----

    private synchronized void schedule(long delayMs, int gen) {
        if (!running || gen != generation || authBlocked) {
            return;
        }
        scheduled = executor.schedule(() -> poll(gen), delayMs, TimeUnit.MILLISECONDS);
    }

    /**
     * One tick: up to two requests in parallel; the next tick is scheduled once both have finished, so a
     * failing feed delays but never blocks the other.
     */
    private static final class Tick {
        final AtomicInteger pending;
        boolean immediate;
        long delayMs;
        int errors;
        long retryAfterSeconds;

        Tick(int pending) {
            this.pending = new AtomicInteger(pending);
        }
    }

    private void poll(int gen) {
        if (!running || gen != generation) {
            return;
        }
        if (!isEnabled()) {
            // Toggled off without a config event reaching us; stop quietly
            stop();
            return;
        }
        boolean drops = config.showTeamDropNotifications();
        boolean completions = config.showTileCompletedNotifications();
        synchronized (this) {
            // A feed that is switched off forgets its cursor, so it baselines again when switched on
            if (!drops) {
                resetDrops();
            }
            if (!completions) {
                resetCompletions();
            }
        }
        Tick tick = new Tick((drops ? 1 : 0) + (completions ? 1 : 0));
        if (drops) {
            String since = cursor;
            try {
                apiService.fetchTeamDrops(since, PAGE_LIMIT,
                        response -> onResponse(gen, tick, since, response),
                        error -> onError(gen, tick, error, this::resetDrops));
            } catch (RuntimeException e) {
                log.warn("Team drop poll failed", e);
                onError(gen, tick, new ApiError(ApiError.NO_RESPONSE, e.getMessage()), this::resetDrops);
            }
        }
        if (completions) {
            String since = completionCursor;
            try {
                apiService.fetchTeamCompletions(since, PAGE_LIMIT,
                        response -> onCompletionsResponse(gen, tick, since, response),
                        error -> onError(gen, tick, error, this::resetCompletions));
            } catch (RuntimeException e) {
                log.warn("Team completion poll failed", e);
                onError(gen, tick, new ApiError(ApiError.NO_RESPONSE, e.getMessage()), this::resetCompletions);
            }
        }
    }

    private void onResponse(int gen, Tick tick, String requestedSince, TeamDropsResponse response) {
        List<TeamDropsResponse.Drop> fresh;
        synchronized (this) {
            if (gen != generation || !running) {
                return;
            }
            try {
                fresh = applyResponse(requestedSince, response, accountName.get(), config.teamDropMinValue());
            } catch (RuntimeException e) {
                log.warn("Team drop response could not be applied", e);
                fresh = List.of();
            }
            finishFeed(gen, tick, response.isHasMore() && !response.isResync(), response.getPollIntervalMs());
        }
        if (!fresh.isEmpty()) {
            show(fresh);
        }
    }

    private void onCompletionsResponse(int gen, Tick tick, String requestedSince, TeamCompletionsResponse response) {
        CompletionBatch batch;
        synchronized (this) {
            if (gen != generation || !running) {
                return;
            }
            try {
                batch = applyCompletions(requestedSince, response, currentBingoId.get());
            } catch (RuntimeException e) {
                log.warn("Team completion response could not be applied", e);
                batch = new CompletionBatch(List.of(), false);
            }
            finishFeed(gen, tick, response.isHasMore() && !response.isResync(), response.getPollIntervalMs());
        }
        if (batch.refreshBoard) {
            try {
                boardRefresh.run();
            } catch (RuntimeException e) {
                log.debug("Board refresh after tile completion failed", e);
            }
        }
        if (!batch.shown.isEmpty()) {
            showCompletions(batch.shown);
        }
    }

    private void onError(int gen, Tick tick, ApiError error, Runnable resetFeed) {
        synchronized (this) {
            if (gen != generation || !running) {
                return;
            }
            int status = error.getStatusCode();
            if (status == 401 || status == 403) {
                log.warn("Team feeds: not authorized ({}), polling stopped until the API key changes", status);
                authBlocked = true;
                return;
            }
            if (status == 400) {
                // Cursor rejected: re-baseline this feed
                resetFeed.run();
                finishFeed(gen, tick, false, 0);
                return;
            }
            tick.errors++;
            tick.retryAfterSeconds = Math.max(tick.retryAfterSeconds, error.getRetryAfterSeconds());
            log.debug("Team feed poll failed ({})", status);
            finishFeed(gen, tick, false, 0);
        }
    }

    /**
     * Records the outcome of one feed and schedules the next tick after the last one finished. Must be
     * called with the lock held.
     */
    private void finishFeed(int gen, Tick tick, boolean hasMore, long serverIntervalMs) {
        tick.immediate |= hasMore;
        tick.delayMs = Math.max(tick.delayMs, intervalMs(serverIntervalMs));
        if (tick.pending.decrementAndGet() > 0) {
            return;
        }
        long delay;
        if (tick.errors > 0) {
            failures++;
            delay = errorDelayMs(failures, DEFAULT_INTERVAL_MS, tick.retryAfterSeconds, random.nextDouble());
        } else {
            failures = 0;
            delay = tick.immediate ? 0 : tick.delayMs;
        }
        schedule(delay, gen);
    }

    /**
     * Applies a response to cursor and seen ids and returns the drops that deserve a popup. Package-private
     * and free of I/O so it can be tested directly.
     */
    synchronized List<TeamDropsResponse.Drop> applyResponse(String requestedSince, TeamDropsResponse response, String ownName, long minValue) {
        if (response.isResync()) {
            resetState();
            return List.of();
        }
        if (response.getCursor() != null) {
            cursor = response.getCursor();
        }
        if (requestedSince == null || response.getDrops() == null) {
            // Baseline request: nothing to show, even if the server sent something
            return List.of();
        }

        List<TeamDropsResponse.Drop> result = new ArrayList<>();
        String own = normalizeName(ownName);
        for (TeamDropsResponse.Drop drop : response.getDrops()) {
            if (drop == null || drop.getId() == null || !seen.add(drop.getId())) {
                continue;
            }
            if (!shouldShow(drop, own, minValue)) {
                continue;
            }
            if (result.size() < MAX_POPUPS_PER_POLL) {
                result.add(drop);
            }
        }
        return result;
    }

    /**
     * Result of a completion response: the completions that deserve a popup and whether the shown board
     * should be reloaded.
     */
    static final class CompletionBatch {
        final List<TeamCompletionsResponse.Completion> shown;
        final boolean refreshBoard;

        CompletionBatch(List<TeamCompletionsResponse.Completion> shown, boolean refreshBoard) {
            this.shown = shown;
            this.refreshBoard = refreshBoard;
        }
    }

    /**
     * Completion counterpart of {@link #applyResponse}. A completion is new when its id and completedAt
     * were not seen, so a tile that is completed again (same id, new time) shows again. The board refresh
     * is requested at most once per response, whatever the number of completions.
     */
    synchronized CompletionBatch applyCompletions(String requestedSince, TeamCompletionsResponse response, String bingoId) {
        if (response.isResync()) {
            resetCompletions();
            return new CompletionBatch(List.of(), false);
        }
        if (response.getCursor() != null) {
            completionCursor = response.getCursor();
        }
        if (requestedSince == null || response.getCompletions() == null) {
            return new CompletionBatch(List.of(), false);
        }

        List<TeamCompletionsResponse.Completion> result = new ArrayList<>();
        boolean refresh = false;
        for (TeamCompletionsResponse.Completion completion : response.getCompletions()) {
            if (completion == null || completion.getId() == null
                    || !seenCompletions.add(completion.getId() + "@" + completion.getCompletedAt())) {
                continue;
            }
            if (bingoId != null && bingoId.equals(completion.getBingoId())) {
                refresh = true;
            }
            if (result.size() < MAX_COMPLETIONS_PER_POLL) {
                result.add(completion);
            }
        }
        return new CompletionBatch(result, refresh);
    }

    static boolean shouldShow(TeamDropsResponse.Drop drop, String normalizedOwnName, long minValue) {
        if ("rejected".equalsIgnoreCase(drop.getStatus()) || drop.getItem() == null) {
            return false;
        }
        String player = drop.getPlayer() == null ? "" : normalizeName(drop.getPlayer().getRunescapeName());
        if (!normalizedOwnName.isEmpty() && normalizedOwnName.equals(player)) {
            return false;
        }
        return drop.getItem().getValue() >= minValue;
    }

    /**
     * Case-insensitive, with underscores and non-breaking spaces treated as spaces.
     */
    static String normalizeName(String name) {
        if (name == null) {
            return "";
        }
        return name.replace('_', ' ').replace(' ', ' ').trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    static long intervalMs(long serverIntervalMs) {
        if (serverIntervalMs <= 0) {
            return DEFAULT_INTERVAL_MS;
        }
        return Math.max(MIN_INTERVAL_MS, serverIntervalMs);
    }

    /**
     * Unjittered backoff: twice the base per consecutive failure (20s, 40s, 80s for a 10s base), capped.
     */
    static long backoffMs(int failures, long baseMs) {
        long delay = baseMs;
        for (int i = 0; i < failures && delay < MAX_BACKOFF_MS; i++) {
            delay *= 2;
        }
        return Math.min(delay, MAX_BACKOFF_MS);
    }

    /**
     * Delay before the retry: backoff with +-20% jitter ({@code roll} in [0, 1)), at least the server's
     * Retry-After, never above the cap.
     */
    static long errorDelayMs(int failures, long baseMs, long retryAfterSeconds, double roll) {
        long backoff = backoffMs(failures, baseMs);
        long jittered = Math.round(backoff * (1 - JITTER + 2 * JITTER * roll));
        long delay = Math.max(jittered, retryAfterSeconds > 0 ? retryAfterSeconds * 1000 : 0);
        return Math.min(delay, MAX_BACKOFF_MS);
    }

    // ---- Popups ----

    private void show(List<TeamDropsResponse.Drop> drops) {
        // Item names need the client thread
        clientThread.invoke(() -> {
            for (TeamDropsResponse.Drop drop : drops) {
                if (!isEnabled()) {
                    return;
                }
                overlay.enqueue(toNotification(drop, itemName(drop.getItem().getItemId()), config.dropUncommonValue(), config.dropRareValue(), config.dropEpicValue(), config.dropLegendaryValue()));
            }
        });
    }

    private void showCompletions(List<TeamCompletionsResponse.Completion> completions) {
        clientThread.invoke(() -> {
            boolean shown = false;
            for (TeamCompletionsResponse.Completion completion : completions) {
                if (!isEnabled() || !config.showTileCompletedNotifications()) {
                    break;
                }
                overlay.enqueue(toNotification(completion));
                shown = true;
            }
            if (shown && config.tileCompletedSound()) {
                client.playSoundEffect(SoundEffectID.UI_BOOP);
            }
        });
    }

    static TileCompletedNotification toNotification(TeamCompletionsResponse.Completion completion) {
        int points = completion.getTile() == null ? 0 : completion.getTile().getPoints();
        String title = completion.getTileTitle() == null ? "Tile" : completion.getTileTitle();
        return new TileCompletedNotification(title, points, completion.getTeamName());
    }

    static DropNotification toNotification(TeamDropsResponse.Drop drop, String itemName, long uncommon, long rare, long epic, long legendary) {
        TeamDropsResponse.Item item = drop.getItem();
        DropTier tier = DropTierResolver.resolve(item.getValue(), uncommon, rare, epic, legendary);
        String player = drop.getPlayer() == null ? null : drop.getPlayer().getRunescapeName();
        return new DropNotification(item.getItemId(), itemName, Math.max(1, item.getQuantity()), item.getValue(), tier,
                drop.getTileTitle(), 0, null, player);
    }

    private String itemName(int itemId) {
        try {
            return itemManager.getItemComposition(itemId).getName();
        } catch (Exception e) {
            log.debug("Failed to get item name for ID {}", itemId, e);
            return "Item #" + itemId;
        }
    }

    // Test access
    String getCursor() {
        return cursor;
    }

    String getCompletionCursor() {
        return completionCursor;
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.bingoscape.BingoScapeConfig;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Non-blocking cache for tile header images (usually OSRS wiki URLs).
 * Lookups never block: a miss starts a background download or scale and returns null,
 * so callers can poll from the render loop every frame.
 */
@Slf4j
@Singleton
public class TileImageCache {
    private static final int MAX_SOURCES = 96;
    private static final int MAX_SCALED = 256;
    private static final int MAX_SOURCE_EDGE = 512;
    private static final int MAX_DOWNLOAD_BYTES = 8 * 1024 * 1024;
    private static final long FAILURE_COOLDOWN_MS = 60_000;

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;
    private final BingoScapeConfig config;

    private final Map<String, BufferedImage> sources = Collections.synchronizedMap(lruMap(MAX_SOURCES));
    private final Map<String, BufferedImage> scaled = Collections.synchronizedMap(lruMap(MAX_SCALED));
    private final Set<String> inFlight = ConcurrentHashMap.newKeySet();
    private final Map<String, Long> failedAt = new ConcurrentHashMap<>();
    private final AtomicInteger generation = new AtomicInteger();

    @Inject
    public TileImageCache(OkHttpClient httpClient, ScheduledExecutorService executor, BingoScapeConfig config) {
        this.httpClient = httpClient;
        this.executor = executor;
        this.config = config;
    }

    /**
     * Returns the image scaled to fit inside {@code maxWidth x maxHeight} (aspect ratio kept),
     * or null if it is not ready yet. A miss schedules the download and/or scale.
     */
    public BufferedImage getScaled(String url, int maxWidth, int maxHeight) {
        if (maxWidth <= 0 || maxHeight <= 0) {
            return null;
        }

        String resolved = resolve(url);
        if (resolved == null) {
            return null;
        }

        String key = resolved + "|" + maxWidth + "|" + maxHeight;
        BufferedImage hit = scaled.get(key);
        if (hit != null) {
            return hit;
        }

        BufferedImage source = sources.get(resolved);
        if (source == null) {
            fetch(resolved);
            return null;
        }

        scheduleScale(key, source, maxWidth, maxHeight);
        return null;
    }

    /**
     * Returns the downloaded (unscaled) image if available, without scheduling anything.
     */
    public BufferedImage getSource(String url) {
        String resolved = resolve(url);
        return resolved == null ? null : sources.get(resolved);
    }

    public boolean hasFailed(String url) {
        String resolved = resolve(url);
        if (resolved == null) {
            return true;
        }
        Long failed = failedAt.get(resolved);
        return failed != null && System.currentTimeMillis() - failed < FAILURE_COOLDOWN_MS;
    }

    public void prefetch(Collection<String> urls) {
        for (String url : urls) {
            String resolved = resolve(url);
            if (resolved != null && !sources.containsKey(resolved)) {
                fetch(resolved);
            }
        }
    }

    public void clear() {
        generation.incrementAndGet();
        sources.clear();
        scaled.clear();
        failedAt.clear();
        // inFlight is left alone: running requests remove themselves, and the generation check drops their results
    }

    private void fetch(String url) {
        if (hasFailed(url) || !inFlight.add(url)) {
            return;
        }

        HttpUrl httpUrl = HttpUrl.parse(url);
        if (httpUrl == null) {
            markFailed(url);
            inFlight.remove(url);
            return;
        }

        int startGeneration = generation.get();
        Request request = new Request.Builder().url(httpUrl).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.debug("Failed to download tile image {}", url, e);
                markFailed(url);
                inFlight.remove(url);
            }

            @Override
            public void onResponse(Call call, Response response) {
                try (ResponseBody body = response.body()) {
                    if (!response.isSuccessful() || body == null || body.contentLength() > MAX_DOWNLOAD_BYTES) {
                        log.debug("Tile image {} not usable (HTTP {})", url, response.code());
                        markFailed(url);
                        return;
                    }

                    byte[] bytes = readCapped(body.byteStream());
                    BufferedImage image = bytes == null ? null : ImageIO.read(new ByteArrayInputStream(bytes));
                    if (image == null) {
                        log.debug("Tile image {} could not be decoded", url);
                        markFailed(url);
                        return;
                    }

                    if (generation.get() == startGeneration) {
                        sources.put(url, downscale(image));
                        failedAt.remove(url);
                    }
                } catch (IOException e) {
                    log.debug("Failed to read tile image {}", url, e);
                    markFailed(url);
                } finally {
                    inFlight.remove(url);
                }
            }
        });
    }

    private void scheduleScale(String key, BufferedImage source, int maxWidth, int maxHeight) {
        if (!inFlight.add(key)) {
            return;
        }

        int startGeneration = generation.get();
        executor.submit(() -> {
            try {
                BufferedImage result = fit(source, maxWidth, maxHeight);
                if (generation.get() == startGeneration) {
                    scaled.put(key, result);
                }
            } catch (Exception e) {
                log.debug("Failed to scale tile image", e);
            } finally {
                inFlight.remove(key);
            }
        });
    }

    private String resolve(String url) {
        if (url == null || url.trim().isEmpty()) {
            return null;
        }

        String trimmed = url.trim();
        if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
            return trimmed;
        }
        if (trimmed.startsWith("//")) {
            return "https:" + trimmed;
        }

        // Relative path: resolve against the configured API base URL
        String base = config.apiBaseUrl();
        if (base == null || base.isEmpty()) {
            return null;
        }
        if (base.endsWith("/")) {
            base = base.substring(0, base.length() - 1);
        }
        return base + (trimmed.startsWith("/") ? "" : "/") + trimmed;
    }

    private void markFailed(String url) {
        failedAt.put(url, System.currentTimeMillis());
    }

    private static byte[] readCapped(InputStream in) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buffer = new byte[8192];
        int total = 0;
        int read;
        while ((read = in.read(buffer)) != -1) {
            total += read;
            if (total > MAX_DOWNLOAD_BYTES) {
                return null;
            }
            out.write(buffer, 0, read);
        }
        return out.toByteArray();
    }

    private static BufferedImage downscale(BufferedImage image) {
        int longest = Math.max(image.getWidth(), image.getHeight());
        if (longest <= MAX_SOURCE_EDGE) {
            return image;
        }
        return fit(image, MAX_SOURCE_EDGE, MAX_SOURCE_EDGE);
    }

    static BufferedImage fit(BufferedImage image, int maxWidth, int maxHeight) {
        double ratio = Math.min((double) maxWidth / image.getWidth(), (double) maxHeight / image.getHeight());
        int width = Math.max(1, (int) Math.round(image.getWidth() * ratio));
        int height = Math.max(1, (int) Math.round(image.getHeight() * ratio));
        return ImageUtil.resizeImage(image, width, height);
    }

    private static <V> Map<String, V> lruMap(int maxEntries) {
        return new LinkedHashMap<String, V>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, V> eldest) {
                return size() > maxEntries;
            }
        };
    }
}

package org.bingoscape.services;

import lombok.extern.slf4j.Slf4j;
import org.bingoscape.BingoScapePlugin;
import org.bingoscape.models.Bingo;
import org.bingoscape.models.Goal;
import org.bingoscape.models.GoalTreeNode;
import org.bingoscape.models.Tile;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Matches game events (item drops, skill levels, etc.) to tile requirements
 * to determine when tiles can be auto-submitted.
 *
 * This service queries the current bingo state from the plugin on-demand,
 * ensuring it's always in sync without requiring manual updates.
 */
@Slf4j
@Singleton
public class TileRequirementMatcher {
    // Maps itemId to list of tiles that require that item
    private volatile Map<Integer, List<UUID>> itemToTilesMap = new ConcurrentHashMap<>();

    // Maps itemId to the goal tree nodes that contain it (for checking restrictions)
    private volatile Map<Integer, List<GoalTreeNode>> itemToGoalMap = new ConcurrentHashMap<>();

    // Plugin reference to query current bingo state
    @Inject
    private BingoScapePlugin plugin;

    /**
     * Rebuilds the lookup maps from the current bingo data.
     * Queries the plugin for the current bingo state and parses the goalTree structure
     * to find all item-based goals.
     */
    public void rebuildLookupMaps() {
        Map<Integer, List<UUID>> newItemToTilesMap = new ConcurrentHashMap<>();
        Map<Integer, List<GoalTreeNode>> newItemToGoalMap = new ConcurrentHashMap<>();

        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null || currentBingo.getTiles() == null) {
            log.warn("Cannot rebuild maps: currentBingo or tiles is null");
            return;
        }

        log.debug("Rebuilding lookup maps for {} tiles", currentBingo.getTiles().size());

        for (Tile tile : currentBingo.getTiles()) {
            // Skip tiles that are already approved
            if (isTileApproved(tile)) {
                log.debug("Skipping tile {} (already approved)", tile.getId());
                continue;
            }

            // Parse goalTree if available (new API format)
            if (tile.getGoalTree() != null && !tile.getGoalTree().isEmpty()) {
                log.debug("Tile {} has goalTree with {} nodes", tile.getId(), tile.getGoalTree().size());
                parseGoalTreeForItems(tile, tile.getGoalTree(), newItemToTilesMap, newItemToGoalMap);
            }
            // Fallback to flat goals list (backwards compatibility)
//            else if (tile.getGoals() != null && !tile.getGoals().isEmpty()) {
//                log.debug("Tile {} has flat goals list with {} goals", tile.getId(), tile.getGoals().size());
//                for (Goal goal : tile.getGoals()) {
//                    if ("item".equals(goal.getGoalType()) && goal.getItemId() != null) {
//                        itemToTilesMap.computeIfAbsent(goal.getItemId(), k -> new ArrayList<>())
//                                .add(tile.getId());
//                        log.debug("Added item {} -> tile {}", goal.getItemId(), tile.getId());
//                    }
//                }
//            } else {
//                log.debug("Tile {} has no goals or goalTree", tile.getId());
//            }
        }

        itemToTilesMap = newItemToTilesMap;
        itemToGoalMap = newItemToGoalMap;

        log.debug("Built item lookup map with {} unique items mapping to tiles: {}",
            itemToTilesMap.size(), itemToTilesMap.keySet());
    }

    /**
     * Recursively parses a goal tree to find all item goals.
     */
    private void parseGoalTreeForItems(Tile tile, List<GoalTreeNode> nodes, Map<Integer, List<UUID>> newItemToTilesMap, Map<Integer, List<GoalTreeNode>> newItemToGoalMap) {
        if (nodes == null) {
            return;
        }

        for (GoalTreeNode node : nodes) {
            log.debug("Parsing node: type={}, isItemGoal={}, isGroup={}",
                node.getType(), node.isItemGoal(), node.isGroup());

            if (node.isItemGoal() && node.getItemGoal() != null && node.getItemGoal().getItemId() != null) {
                // Found an item goal, add to lookup maps
                int itemId = node.getItemGoal().getItemId();
                newItemToTilesMap.computeIfAbsent(itemId, k -> new ArrayList<>())
                        .add(tile.getId());
                newItemToGoalMap.computeIfAbsent(itemId, k -> new ArrayList<>())
                        .add(node);
                log.debug("Added item {} -> tile {} from goalTree", itemId, tile.getId());
            } else if (node.isGroup() && node.getChildren() != null) {
                // Recursively process child nodes
                log.debug("Recursing into group with {} children", node.getChildren().size());
                parseGoalTreeForItems(tile, node.getChildren(), newItemToTilesMap, newItemToGoalMap);
            } else {
                log.debug("Node skipped: type={}, goalType={}, hasItemGoal={}, hasChildren={}",
                    node.getType(), node.getGoalType(), node.getItemGoal() != null,
                    node.getChildren() != null);
            }
        }
    }

    /**
     * Checks if an item drop matches any tile requirements.
     *
     * @param itemId The OSRS item ID
     * @param npcId  The NPC ID (optional, can be null)
     * @return true if this item is required for any incomplete tile
     */
    public boolean isRequiredItem(int itemId, Integer npcId) {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return false;
        }

        // Check if this item is tracked in our goal map
        List<GoalTreeNode> goalNodes = itemToGoalMap.get(itemId);
        if (goalNodes == null || goalNodes.isEmpty()) {
            return false;
        }

        // Item is tracked - check if any associated tile is not yet approved
        List<UUID> matchingTileIds = itemToTilesMap.get(itemId);
        if (matchingTileIds == null || matchingTileIds.isEmpty()) {
            return false;
        }

        for (UUID tileId : matchingTileIds) {
            Tile tile = getTileById(tileId);
            if (tile != null && !isTileApproved(tile)) {
                // Check if the specific goal for this item is incomplete
                // Only return true if there's at least one incomplete goal for this item
                if (!isGoalCompleteForItem(tile, itemId)) {
                    return true; // Found an incomplete goal that needs this item
                }
            }
        }

        return false;
    }

    /**
     * Gets all tiles that match the given item and optional NPC.
     *
     * @param itemId The OSRS item ID
     * @param npcId  The NPC ID (optional, can be null)
     * @return List of tile IDs that should be auto-submitted
     */
    public List<UUID> getTilesForItem(int itemId, Integer npcId) {
        List<UUID> result = new ArrayList<>();

        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return result;
        }

        List<UUID> matchingTileIds = itemToTilesMap.get(itemId);
        if (matchingTileIds == null || matchingTileIds.isEmpty()) {
            return result;
        }

        // Check each matching tile
        for (UUID tileId : matchingTileIds) {
            Tile tile = getTileById(tileId);
            if (tile == null || isTileApproved(tile)) {
                continue;
            }

            // CRITICAL: Check if the specific goal for this item is already complete
            // This prevents re-submitting screenshots for goals that are already done
            if (isGoalCompleteForItem(tile, itemId)) {
                log.debug("Skipping tile {} for item {} - goal already complete", tileId, itemId);
                continue;
            }

            // Check if this tile's goals are satisfied
            if (isTileSatisfiedByItem(tile, itemId, npcId)) {
                result.add(tileId);
            }
        }

        return result;
    }

    /**
     * Checks if a tile is relevant for the given item.
     * We don't need to determine if the tile is COMPLETE - just if this item is part of its requirements.
     * The server will validate whether the tile is actually complete after submission.
     */
    private boolean isTileSatisfiedByItem(Tile tile, int itemId, Integer npcId) {
        // The tile is "satisfied" (ready for auto-submission) if:
        // 1. The item is part of ANY goal in the tile's requirements
        // 2. The server will determine if all requirements are met

        // Try goalTree first (new format)
        if (tile.getGoalTree() != null && !tile.getGoalTree().isEmpty()) {
            return containsItemInTree(tile.getGoalTree(), itemId);
        }

        return false;
    }

    /**
     * Recursively checks if an item is part of any goal in the tree.
     * Returns true if the item is relevant to this tile, regardless of AND/OR logic.
     * The server will validate the complete logic after submission.
     */
    private boolean containsItemInTree(List<GoalTreeNode> nodes, int itemId) {
        if (nodes == null || nodes.isEmpty()) {
            return false;
        }

        for (GoalTreeNode node : nodes) {
            if (node.isItemGoal() &&
                node.getItemGoal() != null &&
                node.getItemGoal().getItemId() != null &&
                node.getItemGoal().getItemId() == itemId) {
                // Found the item in this goal
                return true;
            }

            // Recursively check child nodes
            if (node.isGroup() && node.getChildren() != null) {
                if (containsItemInTree(node.getChildren(), itemId)) {
                    return true;
                }
            }
        }

        return false;
    }

    /**
     * Checks if a tile has already been approved (to avoid re-submitting).
     */
    private boolean isTileApproved(Tile tile) {
        return tile.getSubmission() != null && "approved".equals(tile.getSubmission().getStatus());
    }

    /**
     * Checks if a specific goal for an item is already complete.
     * Searches the goal tree for goals matching the itemId and checks their completion status.
     *
     * @param tile The tile to check
     * @param itemId The item ID to look for
     * @return true if ALL goals matching this item are already complete
     */
    private boolean isGoalCompleteForItem(Tile tile, int itemId) {
        if (tile.getGoalTree() == null || tile.getGoalTree().isEmpty()) {
            return false;
        }

        // Find all goal nodes matching this item
        List<GoalTreeNode> matchingGoals = findGoalsForItem(tile.getGoalTree(), itemId);

        if (matchingGoals.isEmpty()) {
            return false; // No goals found for this item
        }

        // Check if ALL matching goals are complete
        // (If there are multiple goals for the same item, all must be complete to skip submission)
        for (GoalTreeNode goal : matchingGoals) {
            if (goal.getProgress() == null || !goal.getProgress().isComplete()) {
                return false; // At least one goal is incomplete
            }
        }

        log.debug("All goals for item {} in tile {} are complete", itemId, tile.getId());
        return true; // All goals for this item are complete
    }

    /**
     * Recursively finds all goal nodes matching the given itemId in the goal tree.
     *
     * @param nodes The goal tree nodes to search
     * @param itemId The item ID to find
     * @return List of matching goal nodes
     */
    private List<GoalTreeNode> findGoalsForItem(List<GoalTreeNode> nodes, int itemId) {
        List<GoalTreeNode> result = new ArrayList<>();

        if (nodes == null || nodes.isEmpty()) {
            return result;
        }

        for (GoalTreeNode node : nodes) {
            if (node.isItemGoal() &&
                node.getItemGoal() != null &&
                node.getItemGoal().getItemId() != null &&
                node.getItemGoal().getItemId() == itemId) {
                // Found a matching goal
                result.add(node);
            }

            // Recursively check child nodes
            if (node.isGroup() && node.getChildren() != null) {
                result.addAll(findGoalsForItem(node.getChildren(), itemId));
            }
        }

        return result;
    }

    /**
     * Gets a tile by its ID from the current bingo.
     */
    private Tile getTileById(UUID tileId) {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null || currentBingo.getTiles() == null) {
            return null;
        }

        return currentBingo.getTiles().stream()
                .filter(t -> t.getId().equals(tileId))
                .findFirst()
                .orElse(null);
    }

    /**
     * Returns true if there are any trackable tiles (tiles with item goals).
     */
    public boolean hasTrackableTiles() {
        return !itemToTilesMap.isEmpty();
    }

    /**
     * Gets statistics about tracked tiles for debugging.
     */
    public String getStats() {
        Bingo currentBingo = plugin.getCurrentBingo();
        if (currentBingo == null) {
            return "No bingo loaded";
        }

        int totalTiles = currentBingo.getTiles() != null ? currentBingo.getTiles().size() : 0;
        int trackableTiles = (int) itemToTilesMap.values().stream()
                .flatMap(List::stream)
                .distinct()
                .count();

        return String.format("Tracking %d items across %d/%d tiles",
                itemToTilesMap.size(), trackableTiles, totalTiles);
    }
}

package org.bingoscape.ui;

import net.runelite.client.ui.ColorScheme;

import java.awt.Color;

/**
 * Colors shared by the board overlay and the side panel.
 */
public final class BingoTheme {
    public static final Color GOLD = new Color(255, 215, 0);
    public static final Color FOREGROUND = Color.WHITE;
    public static final Color MUTED = new Color(156, 163, 175);

    public static final Color CARD_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
    public static final Color CARD_BORDER = ColorScheme.BORDER_COLOR;
    public static final Color BUTTON_BACKGROUND = ColorScheme.MEDIUM_GRAY_COLOR;
    public static final Color BUTTON_HOVER = new Color(255, 255, 255, 40);
    public static final Color BUTTON_BORDER = ColorScheme.BORDER_COLOR;

    // Goal progress colors, matching the BingoScape web app
    public static final Color PROGRESS_COMPLETE = new Color(16, 185, 129);
    public static final Color PROGRESS_PARTIAL = new Color(245, 158, 11);
    public static final Color PROGRESS_NONE = new Color(107, 114, 128);
    public static final Color PROGRESS_BACKGROUND = new Color(31, 41, 55, 200);

    public static final int CORNER_RADIUS = 8;
    public static final int BUTTON_RADIUS = 6;

    private BingoTheme() {
    }

    public static Color withAlpha(Color color, int alpha) {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), Math.max(0, Math.min(255, alpha)));
    }

    public static Color progressColor(int current, boolean complete) {
        if (complete) {
            return PROGRESS_COMPLETE;
        }
        return current > 0 ? PROGRESS_PARTIAL : PROGRESS_NONE;
    }
}

package org.bingoscape.ui;

import net.runelite.client.ui.ColorScheme;
import org.bingoscape.models.Tile;
import org.bingoscape.models.TileSubmissionType;

import java.awt.Color;

/**
 * Colors and labels for tile submission states, shared by the board window and the board overlay.
 */
public final class TileStatusStyle {
    public static final Color PENDING = new Color(59, 130, 246);       // Blue
    public static final Color ACCEPTED = new Color(34, 197, 94);       // Green
    public static final Color NEEDS_ACTION = new Color(234, 179, 8);   // Yellow
    public static final Color DECLINED = new Color(239, 68, 68);       // Red

    private static final Color PENDING_BG = new Color(30, 64, 122);       // Darker blue
    private static final Color ACCEPTED_BG = new Color(17, 99, 47);       // Darker green
    private static final Color NEEDS_ACTION_BG = new Color(117, 89, 4);   // Darker yellow/gold
    private static final Color DECLINED_BG = new Color(120, 34, 34);      // Darker red

    private TileStatusStyle() {
    }

    public static TileSubmissionType statusOf(Tile tile) {
        if (tile == null || tile.getSubmission() == null) {
            return null;
        }
        return tile.getSubmission().getStatus();
    }

    public static boolean isSubmitted(TileSubmissionType status) {
        return status != null && status != TileSubmissionType.NOT_SUBMITTED;
    }

    public static Color background(TileSubmissionType status) {
        if (!isSubmitted(status)) {
            return ColorScheme.DARK_GRAY_COLOR;
        }

        switch (status) {
            case PENDING:
                return PENDING_BG;
            case ACCEPTED:
                return ACCEPTED_BG;
            case REQUIRES_INTERACTION:
                return NEEDS_ACTION_BG;
            case DECLINED:
                return DECLINED_BG;
            default:
                return ColorScheme.DARK_GRAY_COLOR;
        }
    }

    public static Color border(TileSubmissionType status) {
        if (status == null) {
            return ColorScheme.BORDER_COLOR;
        }

        switch (status) {
            case PENDING:
                return PENDING;
            case ACCEPTED:
                return ACCEPTED;
            case REQUIRES_INTERACTION:
                return NEEDS_ACTION;
            case DECLINED:
                return DECLINED;
            default:
                return ColorScheme.BORDER_COLOR;
        }
    }

    public static Color accent(TileSubmissionType status) {
        if (status == null) {
            return Color.LIGHT_GRAY;
        }

        switch (status) {
            case PENDING:
                return PENDING;
            case ACCEPTED:
                return ACCEPTED;
            case REQUIRES_INTERACTION:
                return NEEDS_ACTION;
            case DECLINED:
                return DECLINED;
            default:
                return Color.LIGHT_GRAY;
        }
    }

    public static String hex(TileSubmissionType status) {
        if (status == null) {
            return "#ffffff";
        }

        switch (status) {
            case PENDING:
                return "#3b82f6";
            case ACCEPTED:
                return "#22c55e";
            case REQUIRES_INTERACTION:
                return "#eab308";
            case DECLINED:
                return "#ef4444";
            default:
                return "#ffffff";
        }
    }

    /**
     * Short uppercase label shown on the tile itself, or null when nothing should be shown.
     */
    public static String shortLabel(TileSubmissionType status) {
        if (status == null) {
            return null;
        }

        switch (status) {
            case PENDING:
                return "PENDING";
            case ACCEPTED:
                return "COMPLETED";
            case REQUIRES_INTERACTION:
                return "NEEDS ACTION";
            case DECLINED:
                return "DECLINED";
            default:
                return null;
        }
    }

    public static String displayText(TileSubmissionType status) {
        if (status == null) {
            return "Not Submitted";
        }

        switch (status) {
            case PENDING:
                return "Pending Review";
            case ACCEPTED:
                return "Completed";
            case REQUIRES_INTERACTION:
                return "Needs Action";
            case DECLINED:
                return "Declined";
            default:
                return "Not Submitted";
        }
    }
}

package org.bingoscape.ui.components;

import org.bingoscape.ui.BingoTheme;

import javax.swing.BoxLayout;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/**
 * Rounded card with a vertical layout, the side panel counterpart of the overlay's board background.
 * Never grows taller than its content inside a BoxLayout.
 */
public class CardPanel extends JPanel {
    public CardPanel() {
        setOpaque(false);
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(new EmptyBorder(8, 8, 8, 8));
        setAlignmentX(Component.LEFT_ALIGNMENT);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int r = BingoTheme.CORNER_RADIUS;
            g2.setColor(BingoTheme.CARD_BACKGROUND);
            g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, r, r);
            g2.setColor(BingoTheme.CARD_BORDER);
            g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, r, r);
        } finally {
            g2.dispose();
        }
        super.paintComponent(g);
    }
}

package org.bingoscape.ui.components;

import net.runelite.client.ui.FontManager;
import org.bingoscape.ui.BingoTheme;

import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.border.EmptyBorder;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Rounded flat button styled like the board overlay's header buttons: gray fill, hover wash,
 * dimmed when disabled.
 */
public class FlatButton extends JButton {
    private boolean hovered;

    public FlatButton(String text) {
        this(text, null);
    }

    public FlatButton(String text, Icon icon) {
        super(text, icon);
        setFont(FontManager.getRunescapeSmallFont());
        setForeground(BingoTheme.FOREGROUND);
        setContentAreaFilled(false);
        setFocusPainted(false);
        setBorderPainted(false);
        setOpaque(false);
        setBorder(new EmptyBorder(5, 10, 5, 10));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                repaint();
            }
        });
    }

    @Override
    public void setEnabled(boolean enabled) {
        super.setEnabled(enabled);
        setForeground(enabled ? BingoTheme.FOREGROUND : Color.GRAY);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int r = BingoTheme.BUTTON_RADIUS;
            g2.setColor(isEnabled() ? BingoTheme.BUTTON_BACKGROUND : BingoTheme.withAlpha(BingoTheme.BUTTON_BACKGROUND, 120));
            g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, r, r);
            if (isEnabled() && (hovered || getModel().isPressed())) {
                g2.setColor(BingoTheme.BUTTON_HOVER);
                g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, r, r);
            }
            g2.setColor(BingoTheme.BUTTON_BORDER);
            g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, r, r);
        } finally {
            g2.dispose();
        }
        super.paintComponent(g);
    }
}

