package org.bingoscape.board;

import org.junit.Test;

import java.awt.Rectangle;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BoardLayoutTest {
    // Fixed-mode game viewport
    private static final int FIXED_WIDTH = 765;
    private static final int FIXED_HEIGHT = 503;

    @Test
    public void fiveByFiveFitsFixedViewport() {
        BoardLayout layout = BoardLayout.compute(5, 5, 25, FIXED_WIDTH, FIXED_HEIGHT, 1.0, true);

        assertTrue(layout.width <= FIXED_WIDTH * BoardLayout.VIEWPORT_FILL);
        assertTrue(layout.height <= FIXED_HEIGHT * BoardLayout.VIEWPORT_FILL);
        assertEquals(25, layout.tiles.size());
    }

    @Test
    public void largeViewportUsesScaledDefaultTileSize() {
        BoardLayout layout = BoardLayout.compute(5, 5, 25, 2560, 1440, 1.0, false);
        assertEquals(BoardLayout.TILE_DEFAULT, layout.tileSize);

        BoardLayout scaled = BoardLayout.compute(5, 5, 25, 2560, 1440, 1.5, false);
        assertEquals(144, scaled.tileSize);
    }

    @Test
    public void tileSizeNeverDropsBelowMinimum() {
        BoardLayout layout = BoardLayout.compute(7, 7, 49, FIXED_WIDTH, FIXED_HEIGHT, 1.0, true);
        assertTrue(layout.tileSize >= BoardLayout.TILE_MIN);

        BoardLayout tiny = BoardLayout.compute(10, 10, 100, 300, 200, 1.0, true);
        assertEquals(BoardLayout.TILE_MIN, tiny.tileSize);
    }

    @Test
    public void nonPositiveDimensionsDefaultToFive() {
        BoardLayout layout = BoardLayout.compute(0, -1, 25, 1920, 1080, 1.0, false);

        assertEquals(5, layout.rows);
        assertEquals(5, layout.cols);
    }

    @Test
    public void extraTilesAddRows() {
        BoardLayout layout = BoardLayout.compute(5, 5, 30, 1920, 1080, 1.0, false);

        assertEquals(6, layout.rows);
        assertEquals(30, layout.tiles.size());
    }

    @Test
    public void tileIndexAtMapsCellsAndRejectsGaps() {
        BoardLayout layout = BoardLayout.compute(3, 3, 9, 1920, 1080, 1.0, false);

        Rectangle first = layout.tiles.get(0);
        assertEquals(0, layout.tileIndexAt(first.x, first.y));

        Rectangle last = layout.tiles.get(8);
        assertEquals(8, layout.tileIndexAt(last.x + last.width - 1, last.y + last.height - 1));

        Rectangle middle = layout.tiles.get(4);
        assertEquals(4, layout.tileIndexAt(middle.x + middle.width / 2, middle.y + middle.height / 2));

        // The gap right of the first tile
        assertEquals(-1, layout.tileIndexAt(first.x + first.width + 1, first.y + 1));
        // Header area
        assertEquals(-1, layout.tileIndexAt(first.x, 0));
    }

    @Test
    public void headerButtonsDoNotOverlapTitle() {
        BoardLayout layout = BoardLayout.compute(3, 3, 9, FIXED_WIDTH, FIXED_HEIGHT, 1.0, false);

        assertTrue(layout.title.x + layout.title.width <= layout.pinButton.x);
        assertTrue(layout.pinButton.x + layout.pinButton.width <= layout.reloadButton.x);
        assertTrue(layout.reloadButton.x + layout.reloadButton.width <= layout.closeButton.x);
        assertTrue(layout.closeButton.x + layout.closeButton.width <= layout.width);
        assertEquals(BoardLayout.Button.CLOSE, layout.buttonAt(layout.closeButton.x + 1, layout.closeButton.y + 1));
        assertNull(layout.codephrase);
    }

    @Test
    public void narrowBoardsAreWidenedAndCentered() {
        BoardLayout layout = BoardLayout.compute(1, 1, 1, 1920, 1080, 1.0, false);

        assertEquals(BoardLayout.MIN_WIDTH, layout.width);
        Rectangle grid = layout.gridArea;
        assertEquals(layout.width - grid.x - grid.width, grid.x);
    }
}

package org.bingoscape.board;

import org.bingoscape.models.Bingo;
import org.bingoscape.models.Tile;
import org.bingoscape.models.TileSubmission;
import org.bingoscape.models.TileSubmissionType;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class BoardModelAndTooltipTest {
    private static Tile tile(int index, String title) {
        Tile tile = new Tile();
        tile.setId(UUID.randomUUID());
        tile.setIndex(index);
        tile.setTitle(title);
        tile.setWeight(10);
        return tile;
    }

    @Test
    public void modelSortsACopyAndLeavesBingoTilesUntouched() {
        Tile second = tile(1, "second");
        Tile first = tile(0, "first");
        Bingo bingo = new Bingo();
        List<Tile> original = new ArrayList<>(Arrays.asList(second, first));
        bingo.setTiles(original);

        BoardModel model = BoardModel.of(bingo);

        assertSame(first, model.tiles.get(0));
        assertSame(second, model.tiles.get(1));
        assertSame(second, bingo.getTiles().get(0));
        assertSame(first, model.byId.get(first.getId()));
    }

    @Test
    public void modelHandlesMissingTiles() {
        assertTrue(BoardModel.of(new Bingo()).tiles.isEmpty());
    }

    @Test
    public void tooltipShowsTitleStatusAndEscapesTags() {
        Tile tile = tile(0, "Kill <b>Zulrah</b>");
        tile.setDescription("Get a drop");
        TileSubmission submission = new TileSubmission();
        submission.setStatus(TileSubmissionType.PENDING);
        submission.setSubmissionCount(2);
        tile.setSubmission(submission);

        String tooltip = BoardTooltipBuilder.build(tile);

        assertTrue(tooltip.contains("Kill (b)Zulrah(/b) (10 XP)"));
        assertTrue(tooltip.contains("Pending Review"));
        assertTrue(tooltip.contains("Submissions: 2"));
        assertFalse(tooltip.contains("<b>"));
    }

    @Test
    public void hiddenTileTooltip() {
        Tile tile = tile(0, "secret");
        tile.setHidden(true);

        assertEquals("Hidden tile", BoardTooltipBuilder.build(tile));
    }

    @Test
    public void primaryButtonStatesMatchWindow() {
        Tile tile = tile(0, "t");
        Bingo bingo = new Bingo();
        assertTrue(TileDetailsView.primaryEnabled(tile, bingo));
        assertEquals("Take & Review Screenshot", TileDetailsView.primaryLabel(tile, bingo));

        TileSubmission accepted = new TileSubmission();
        accepted.setStatus(TileSubmissionType.ACCEPTED);
        tile.setSubmission(accepted);
        assertFalse(TileDetailsView.primaryEnabled(tile, bingo));
        assertEquals("Already Completed", TileDetailsView.primaryLabel(tile, bingo));

        // Locked wins over completed, as in the old dialog
        bingo.setLocked(true);
        assertEquals("Submissions locked", TileDetailsView.primaryLabel(tile, bingo));
    }
}

package org.bingoscape.board;

import org.junit.Test;

import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class TextWrapTest {
    private static final FontMetrics FM = metrics();

    private static FontMetrics metrics() {
        Graphics2D g = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB).createGraphics();
        FontMetrics fm = g.getFontMetrics(new Font(Font.MONOSPACED, Font.PLAIN, 12));
        g.dispose();
        return fm;
    }

    @Test
    public void wrapsOnWordBoundaries() {
        int width = FM.stringWidth("aaaa bbbb");
        List<String> lines = TextWrap.wrap("aaaa bbbb cccc dddd", FM, width, 10);

        assertEquals(2, lines.size());
        assertEquals("aaaa bbbb", lines.get(0));
        assertEquals("cccc dddd", lines.get(1));
    }

    @Test
    public void hardBreaksLongWords() {
        int width = FM.stringWidth("aaaa");
        List<String> lines = TextWrap.wrap("aaaaaaaaaa", FM, width, 10);

        assertEquals(3, lines.size());
        for (String line : lines) {
            assertTrue(FM.stringWidth(line) <= width);
        }
    }

    @Test
    public void truncatesWithEllipsis() {
        int width = FM.stringWidth("aaaa bbbb");
        List<String> lines = TextWrap.wrap("aaaa bbbb cccc dddd eeee ffff", FM, width, 2);

        assertEquals(2, lines.size());
        assertTrue(lines.get(1).endsWith(TextWrap.ELLIPSIS));
        assertTrue(FM.stringWidth(lines.get(1)) <= width);
    }

    @Test
    public void keepsExplicitLineBreaks() {
        List<String> lines = TextWrap.wrap("first\nsecond", FM, 1000, 10);

        assertEquals(2, lines.size());
        assertEquals("second", lines.get(1));
    }

    @Test
    public void emptyInputGivesNoLines() {
        assertTrue(TextWrap.wrap(null, FM, 100, 3).isEmpty());
        assertTrue(TextWrap.wrap("   ", FM, 100, 3).isEmpty());
        assertTrue(TextWrap.wrap("text", FM, 0, 3).isEmpty());
    }

    @Test
    public void ellipsizeOnlyShortensWhenNeeded() {
        assertEquals("short", TextWrap.ellipsize("short", FM, 1000));

        int width = FM.stringWidth("abcdef");
        String shortened = TextWrap.ellipsize("abcdefghijkl", FM, width);
        assertTrue(shortened.endsWith(TextWrap.ELLIPSIS));
        assertTrue(FM.stringWidth(shortened) <= width);
    }
}

package org.bingoscape.notifications;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DropNotificationOverlayTest {
    private static final long HOLD = 5000;

    @Test
    public void alphaFadesInHoldsAndFadesOut() {
        assertEquals(0f, DropNotificationOverlay.alpha(0, HOLD, false), 0.001f);
        assertEquals(1f, DropNotificationOverlay.alpha(DropNotificationOverlay.SLIDE_MS, HOLD, false), 0.001f);
        assertEquals(1f, DropNotificationOverlay.alpha(3000, HOLD, false), 0.001f);

        long fadeStart = DropNotificationOverlay.SLIDE_MS + HOLD;
        assertEquals(0.5f, DropNotificationOverlay.alpha(fadeStart + DropNotificationOverlay.FADE_MS / 2, HOLD, false), 0.001f);
        assertEquals(0f, DropNotificationOverlay.alpha(fadeStart + DropNotificationOverlay.FADE_MS, HOLD, false), 0.001f);
    }

    @Test
    public void captionShowsPlayerForTeamDrops() {
        DropNotification own = new DropNotification(1, "Item", 1, 10, DropTier.COMMON, null, 0, null);
        DropNotification team = new DropNotification(1, "Item", 1, 10, DropTier.COMMON, null, 0, null, "Mate");
        assertEquals("Bingo Item", DropNotificationOverlay.caption(own));
        assertEquals("Mate received", DropNotificationOverlay.caption(team));
    }

    @Test
    public void queuedPopupsHoldShorter() {
        long normal = DropNotificationOverlay.totalMs(HOLD, false);
        long hurried = DropNotificationOverlay.totalMs(HOLD, true);
        assertTrue(hurried < normal);
        assertEquals(DropNotificationOverlay.SLIDE_MS + 3000 + DropNotificationOverlay.FADE_MS, hurried);
    }

    @Test
    public void slideProgressIsMonotonicAndBounded() {
        assertEquals(0f, DropNotificationOverlay.slideProgress(0), 0.001f);
        assertEquals(1f, DropNotificationOverlay.slideProgress(DropNotificationOverlay.SLIDE_MS), 0.001f);
        assertEquals(1f, DropNotificationOverlay.slideProgress(10_000), 0.001f);
        float previous = 0;
        for (long t = 0; t <= DropNotificationOverlay.SLIDE_MS; t += 25) {
            float p = DropNotificationOverlay.slideProgress(t);
            assertTrue(p >= previous);
            previous = p;
        }
    }

    @Test
    public void layoutRowsDoNotOverlapAtAnyFontSize() {
        for (int small = 10; small <= 32; small += 2) {
            int big = small + 2;
            DropNotificationOverlay.Layout plain = DropNotificationOverlay.Layout.of(small, big, 8, false);
            assertTrue(plain.nameY >= plain.captionY + plain.pillHeight);
            assertTrue(plain.statY >= plain.nameY + big);
            assertTrue(plain.contentBottom >= plain.statY + small);
            assertEquals(plain.contentBottom, plain.height);

            DropNotificationOverlay.Layout warned = DropNotificationOverlay.Layout.of(small, big, 8, true);
            assertEquals(plain.contentBottom, warned.warningY);
            assertTrue(warned.height >= warned.warningY + small);
        }
    }

    private static DropNotification drop(String name) {
        return new DropNotification(1, name, 1, 10, DropTier.COMMON, null, 0, null);
    }

    private static TileCompletedNotification done(String title) {
        return new TileCompletedNotification(title, 5, "Team");
    }

    private static DropNotificationOverlay overlay() {
        return new DropNotificationOverlay(null, null);
    }

    @Test
    public void completionsComeFirstAndStayFifoWithinPriority() {
        DropNotificationOverlay overlay = overlay();
        overlay.enqueue(drop("d1"));
        overlay.enqueue(done("c1"));
        overlay.enqueue(drop("d2"));
        overlay.enqueue(done("c2"));
        assertEquals("c1", ((TileCompletedNotification) overlay.pollNext()).getTileTitle());
        assertEquals("c2", ((TileCompletedNotification) overlay.pollNext()).getTileTitle());
        assertEquals("d1", ((DropNotification) overlay.pollNext()).getItemName());
        assertEquals("d2", ((DropNotification) overlay.pollNext()).getItemName());
        assertNull(overlay.pollNext());
    }

    @Test
    public void overflowEvictsDropsBeforeCompletions() {
        DropNotificationOverlay overlay = overlay();
        for (int i = 0; i < 10; i++) {
            overlay.enqueue(drop("d" + i));
        }
        overlay.enqueue(drop("late"));
        assertEquals(10, overlay.queueSize());

        overlay.enqueue(done("c1"));
        assertEquals(10, overlay.queueSize());
        assertEquals("c1", ((TileCompletedNotification) overlay.pollNext()).getTileTitle());
        // The oldest drop made room
        assertEquals("d1", ((DropNotification) overlay.pollNext()).getItemName());
    }

    @Test
    public void completionIsDroppedWhenQueueHoldsOnlyCompletions() {
        DropNotificationOverlay overlay = overlay();
        for (int i = 0; i < 10; i++) {
            overlay.enqueue(done("c" + i));
        }
        overlay.enqueue(done("extra"));
        overlay.enqueue(drop("d"));
        assertEquals(10, overlay.queueSize());
        for (int i = 0; i < 10; i++) {
            assertEquals("c" + i, ((TileCompletedNotification) overlay.pollNext()).getTileTitle());
        }
    }

    @Test
    public void completionsHoldOneAndAHalfTimesLonger() {
        assertEquals(7500, DropNotificationOverlay.holdFor(done("c"), HOLD));
        assertEquals(HOLD, DropNotificationOverlay.holdFor(drop("d"), HOLD));
    }
}

package org.bingoscape.notifications;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class DropTierResolverTest {
    private static DropTier tier(long value) {
        return DropTierResolver.resolve(value, 100_000, 1_000_000, 10_000_000, 100_000_000);
    }

    @Test
    public void valueAtThresholdFallsIntoHigherTier() {
        assertEquals(DropTier.COMMON, tier(0));
        assertEquals(DropTier.COMMON, tier(99_999));
        assertEquals(DropTier.UNCOMMON, tier(100_000));
        assertEquals(DropTier.RARE, tier(1_000_000));
        assertEquals(DropTier.EPIC, tier(10_000_000));
        assertEquals(DropTier.LEGENDARY, tier(100_000_000));
        assertEquals(DropTier.LEGENDARY, tier(2_000_000_000L));
    }

    @Test
    public void unsortedThresholdsStayMonotonic() {
        assertEquals(DropTier.UNCOMMON, DropTierResolver.resolve(150, 1000, 100, 10_000, 500));
        assertEquals(DropTier.LEGENDARY, DropTierResolver.resolve(10_000, 1000, 100, 10_000, 500));
    }

    @Test
    public void zeroThresholdDoesNotPromoteWorthlessDrops() {
        assertEquals(DropTier.COMMON, DropTierResolver.resolve(0, 0, 0, 0, 0));
    }

    @Test
    public void tiersHaveDistinctColors() {
        for (DropTier a : DropTier.values()) {
            for (DropTier b : DropTier.values()) {
                assertTrue(a == b || !a.color().equals(b.color()));
            }
        }
    }

    @Test
    public void formatsGpLikeTheGame() {
        assertEquals("0", DropTierResolver.formatGp(0));
        assertEquals("9999", DropTierResolver.formatGp(9_999));
        assertEquals("10k", DropTierResolver.formatGp(10_000));
        assertEquals("12.5k", DropTierResolver.formatGp(12_500));
        assertEquals("250k", DropTierResolver.formatGp(250_000));
        assertEquals("1m", DropTierResolver.formatGp(1_000_000));
        assertEquals("3.3m", DropTierResolver.formatGp(3_250_000));
        assertEquals("100k", DropTierResolver.formatGp(99_960));
        assertEquals("1.1b", DropTierResolver.formatGp(1_100_000_000L));
    }
}

package org.bingoscape.services;

import com.google.gson.Gson;
import org.bingoscape.models.TeamCompletionsResponse;
import org.bingoscape.models.TeamDropsResponse;
import org.bingoscape.notifications.TileCompletedNotification;
import org.bingoscape.notifications.DropNotification;
import org.bingoscape.notifications.DropTier;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TeamDropPollerTest {
    private final TeamDropPoller poller = new TeamDropPoller(null, null, null, null, null, null, null);

    private static TeamDropsResponse.Drop drop(String id, String player, String status, long value) {
        TeamDropsResponse.Drop drop = new TeamDropsResponse.Drop();
        drop.setId(id);
        drop.setStatus(status);
        TeamDropsResponse.Player p = new TeamDropsResponse.Player();
        p.setRunescapeName(player);
        drop.setPlayer(p);
        TeamDropsResponse.Item item = new TeamDropsResponse.Item();
        item.setItemId(4151);
        item.setQuantity(1);
        item.setValue(value);
        drop.setItem(item);
        drop.setTileTitle("Whip");
        return drop;
    }

    private static TeamDropsResponse response(String cursor, TeamDropsResponse.Drop... drops) {
        TeamDropsResponse r = new TeamDropsResponse();
        r.setCursor(cursor);
        r.setDrops(new ArrayList<>(List.of(drops)));
        return r;
    }

    @Test
    public void firstPollOnlyBaselinesAndNeverReplays() {
        List<TeamDropsResponse.Drop> shown = poller.applyResponse(null, response("c1", drop("a", "Mate", "approved", 5)), "Me", 0);
        assertTrue(shown.isEmpty());
        assertEquals("c1", poller.getCursor());
    }

    @Test
    public void cursorAdvancesAndDuplicatesAreSkipped() {
        poller.applyResponse(null, response("c1"), "Me", 0);
        List<TeamDropsResponse.Drop> first = poller.applyResponse("c1", response("c2", drop("a", "Mate", "approved", 5)), "Me", 0);
        assertEquals(1, first.size());
        assertEquals("c2", poller.getCursor());

        List<TeamDropsResponse.Drop> again = poller.applyResponse("c2",
                response("c3", drop("a", "Mate", "approved", 5), drop("b", "Mate", "pending", 5)), "Me", 0);
        assertEquals(1, again.size());
        assertEquals("b", again.get(0).getId());
        assertEquals("c3", poller.getCursor());
    }

    @Test
    public void ownRejectedAndLowValueDropsAreSkipped() {
        List<TeamDropsResponse.Drop> shown = poller.applyResponse("c", response("c2",
                drop("own", "my_name", "approved", 100),
                drop("rej", "Mate", "rejected", 100),
                drop("low", "Mate", "approved", 10),
                drop("ok", "Mate", "approved", 100)), "My Name", 50);
        assertEquals(1, shown.size());
        assertEquals("ok", shown.get(0).getId());
    }

    @Test
    public void resyncDropsCursorAndSeen() {
        poller.applyResponse("c", response("c2", drop("a", "Mate", "approved", 1)), "Me", 0);
        TeamDropsResponse resync = response("c9", drop("z", "Mate", "approved", 1));
        resync.setResync(true);
        assertTrue(poller.applyResponse("c2", resync, "Me", 0).isEmpty());
        assertNull(poller.getCursor());
        // Seen ids were cleared, so "a" counts as new again
        assertEquals(1, poller.applyResponse("c3", response("c4", drop("a", "Mate", "approved", 1)), "Me", 0).size());
    }

    @Test
    public void popupsPerPollAreCapped() {
        TeamDropsResponse.Drop[] drops = new TeamDropsResponse.Drop[12];
        for (int i = 0; i < drops.length; i++) {
            drops[i] = drop("d" + i, "Mate", "approved", 1);
        }
        assertEquals(TeamDropPoller.MAX_POPUPS_PER_POLL, poller.applyResponse("c", response("c2", drops), "Me", 0).size());
    }

    @Test
    public void seenSetIsBounded() {
        for (int i = 0; i < TeamDropPoller.MAX_SEEN + 100; i++) {
            poller.applyResponse("c", response("c", drop("d" + i, "Mate", "approved", 1)), "Me", 0);
        }
        // The oldest id was evicted, the newest is remembered
        assertEquals(1, poller.applyResponse("c", response("c", drop("d0", "Mate", "approved", 1)), "Me", 0).size());
        assertTrue(poller.applyResponse("c", response("c", drop("d" + (TeamDropPoller.MAX_SEEN + 99), "Mate", "approved", 1)), "Me", 0).isEmpty());
    }

    @Test
    public void intervalHonorsServerWithMinimumAndDefault() {
        assertEquals(10_000, TeamDropPoller.intervalMs(0));
        assertEquals(5_000, TeamDropPoller.intervalMs(1_000));
        assertEquals(15_000, TeamDropPoller.intervalMs(15_000));
    }

    @Test
    public void backoffDoublesUpToCap() {
        assertEquals(20_000, TeamDropPoller.backoffMs(1, 10_000));
        assertEquals(40_000, TeamDropPoller.backoffMs(2, 10_000));
        assertEquals(80_000, TeamDropPoller.backoffMs(3, 10_000));
        assertEquals(120_000, TeamDropPoller.backoffMs(4, 10_000));
        assertEquals(120_000, TeamDropPoller.backoffMs(30, 10_000));
    }

    @Test
    public void errorDelayAppliesJitterRetryAfterAndCap() {
        assertEquals(16_000, TeamDropPoller.errorDelayMs(1, 10_000, -1, 0.0));
        assertEquals(24_000, TeamDropPoller.errorDelayMs(1, 10_000, -1, 1.0));
        assertEquals(60_000, TeamDropPoller.errorDelayMs(1, 10_000, 60, 0.5));
        assertEquals(120_000, TeamDropPoller.errorDelayMs(1, 10_000, 600, 0.5));
        assertEquals(120_000, TeamDropPoller.errorDelayMs(10, 10_000, -1, 1.0));
    }

    @Test
    public void namesAreNormalized() {
        assertEquals("my name", TeamDropPoller.normalizeName("  My_Name "));
        assertEquals("my name", TeamDropPoller.normalizeName("My Name"));
        assertEquals("", TeamDropPoller.normalizeName(null));
    }

    @Test
    public void gsonParsesResponse() {
        String json = "{\"cursor\":\"abc\",\"hasMore\":true,\"resync\":false,\"pollIntervalMs\":8000,\"unknown\":1,"
                + "\"drops\":[{\"id\":\"1\",\"createdAt\":\"2026-01-01T00:00:00Z\",\"status\":\"approved\",\"eventId\":\"e\","
                + "\"bingoId\":\"b\",\"teamId\":\"t\",\"teamName\":\"Team\",\"tileId\":\"ti\",\"tileTitle\":\"Whip\","
                + "\"player\":{\"runescapeName\":\"Mate\"},\"item\":{\"itemId\":4151,\"quantity\":2,\"value\":5000000},"
                + "\"source\":{\"name\":\"Abyssal demon\",\"type\":\"npc\",\"npcId\":415},\"imageUrl\":null}]}";
        TeamDropsResponse r = new Gson().fromJson(json, TeamDropsResponse.class);
        assertEquals("abc", r.getCursor());
        assertTrue(r.isHasMore());
        assertEquals(8000, r.getPollIntervalMs());
        TeamDropsResponse.Drop d = r.getDrops().get(0);
        assertEquals("Mate", d.getPlayer().getRunescapeName());
        assertEquals(2, d.getItem().getQuantity());
        assertEquals(5_000_000L, d.getItem().getValue());
        assertEquals(Integer.valueOf(415), d.getSource().getNpcId());
    }

    @Test
    public void notificationCarriesPlayerAndTier() {
        DropNotification n = TeamDropPoller.toNotification(drop("a", "Mate", "approved", 5_000_000), "Abyssal whip",
                100_000, 1_000_000, 10_000_000, 100_000_000);
        assertEquals("Mate", n.getPlayerName());
        assertEquals(DropTier.RARE, n.getTier());
        assertEquals("Whip", n.getTileTitle());
    }

    private static TeamCompletionsResponse.Completion completion(String id, String at, String bingoId) {
        TeamCompletionsResponse.Completion c = new TeamCompletionsResponse.Completion();
        c.setId(id);
        c.setCompletedAt(at);
        c.setBingoId(bingoId);
        c.setTileTitle("Tile " + id);
        c.setTeamName("Team");
        TeamCompletionsResponse.Tile t = new TeamCompletionsResponse.Tile();
        t.setPoints(7);
        c.setTile(t);
        return c;
    }

    private static TeamCompletionsResponse completions(String cursor, TeamCompletionsResponse.Completion... items) {
        TeamCompletionsResponse r = new TeamCompletionsResponse();
        r.setCursor(cursor);
        r.setCompletions(new ArrayList<>(List.of(items)));
        return r;
    }

    @Test
    public void completionBaselineShowsNothing() {
        TeamDropPoller.CompletionBatch batch = poller.applyCompletions(null, completions("c1", completion("a", "t1", "b")), "b");
        assertTrue(batch.shown.isEmpty());
        assertFalse(batch.refreshBoard);
        assertEquals("c1", poller.getCompletionCursor());
    }

    @Test
    public void completionsDedupOnIdAndCompletedAt() {
        poller.applyCompletions(null, completions("c1"), "b");
        assertEquals(1, poller.applyCompletions("c1", completions("c2", completion("a", "t1", "b")), "b").shown.size());
        assertTrue(poller.applyCompletions("c2", completions("c3", completion("a", "t1", "b")), "b").shown.isEmpty());
        // Same tile completed again later
        TeamDropPoller.CompletionBatch again = poller.applyCompletions("c3", completions("c4", completion("a", "t2", "b")), "b");
        assertEquals(1, again.shown.size());
        assertEquals("c4", poller.getCompletionCursor());
    }

    @Test
    public void nullCompletionsListIsEmpty() {
        TeamCompletionsResponse r = new TeamCompletionsResponse();
        r.setCursor("c2");
        TeamDropPoller.CompletionBatch batch = poller.applyCompletions("c1", r, "b");
        assertTrue(batch.shown.isEmpty());
        assertEquals("c2", poller.getCompletionCursor());
    }

    @Test
    public void completionsArePerPollCappedButAllRequestRefreshOnce() {
        TeamDropPoller.CompletionBatch batch = poller.applyCompletions("c", completions("c2",
                completion("1", "t", "other"), completion("2", "t", "b"), completion("3", "t", "b"),
                completion("4", "t", "b"), completion("5", "t", "b")), "b");
        assertEquals(TeamDropPoller.MAX_COMPLETIONS_PER_POLL, batch.shown.size());
        assertTrue(batch.refreshBoard);
    }

    @Test
    public void refreshOnlyForCurrentBingo() {
        assertFalse(poller.applyCompletions("c", completions("c2", completion("1", "t", "other")), "b").refreshBoard);
        assertFalse(poller.applyCompletions("c2", completions("c3", completion("2", "t", "b")), null).refreshBoard);
    }

    @Test
    public void completionResyncDropsCursorAndSeenIndependentOfDrops() {
        poller.applyResponse("c", response("d2", drop("a", "Mate", "approved", 1)), "Me", 0);
        poller.applyCompletions("c", completions("c2", completion("a", "t", "b")), "b");
        TeamCompletionsResponse resync = completions("c9", completion("z", "t", "b"));
        resync.setResync(true);
        assertTrue(poller.applyCompletions("c2", resync, "b").shown.isEmpty());
        assertNull(poller.getCompletionCursor());
        assertEquals("d2", poller.getCursor());
        // Seen set was cleared: "a" shows again
        assertEquals(1, poller.applyCompletions("c9", completions("c10", completion("a", "t", "b")), "b").shown.size());
    }

    @Test
    public void completionIdsDoNotCollideWithDropIds() {
        poller.applyResponse("c", response("d2", drop("a", "Mate", "approved", 1)), "Me", 0);
        assertEquals(1, poller.applyCompletions("c", completions("c2", completion("a", "t", "b")), "b").shown.size());
    }

    @Test
    public void gsonParsesCompletionsWithUnknownFields() {
        String json = "{\"cursor\":\"abc\",\"hasMore\":true,\"resync\":false,\"pollIntervalMs\":8000,\"extra\":{},"
                + "\"completions\":[{\"id\":\"1\",\"completedAt\":\"2026-01-01T00:00:00Z\",\"eventId\":\"e\",\"bingoId\":\"b\","
                + "\"teamId\":\"t\",\"teamName\":\"Team\",\"tileId\":\"ti\",\"tileTitle\":\"Whip\",\"x\":1,"
                + "\"tile\":{\"points\":10,\"tier\":3,\"other\":true}}]}";
        TeamCompletionsResponse r = new Gson().fromJson(json, TeamCompletionsResponse.class);
        assertEquals("abc", r.getCursor());
        assertTrue(r.isHasMore());
        assertEquals(8000, r.getPollIntervalMs());
        TeamCompletionsResponse.Completion c = r.getCompletions().get(0);
        assertEquals("b", c.getBingoId());
        assertEquals("Whip", c.getTileTitle());
        assertEquals(10, c.getTile().getPoints());

        assertNull(new Gson().fromJson("{\"cursor\":\"x\"}", TeamCompletionsResponse.class).getCompletions());
    }

    @Test
    public void completionNotificationCarriesTitlePointsAndTeam() {
        TileCompletedNotification n = TeamDropPoller.toNotification(completion("a", "t", "b"));
        assertEquals("Tile a", n.getTileTitle());
        assertEquals(7, n.getPoints());
        assertEquals("Team", n.getTeamName());
    }
}

package org.bingoscape.ui;

import net.runelite.client.ui.ColorScheme;
import org.bingoscape.models.TileSubmissionType;
import org.junit.Test;

import java.awt.Color;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TileStatusStyleTest {
    @Test
    public void submittedStatesHaveDistinctColorsAndLabels() {
        assertEquals(new Color(30, 64, 122), TileStatusStyle.background(TileSubmissionType.PENDING));
        assertEquals(new Color(34, 197, 94), TileStatusStyle.border(TileSubmissionType.ACCEPTED));
        assertEquals(new Color(234, 179, 8), TileStatusStyle.accent(TileSubmissionType.REQUIRES_INTERACTION));
        assertEquals("#ef4444", TileStatusStyle.hex(TileSubmissionType.DECLINED));
        assertEquals("NEEDS ACTION", TileStatusStyle.shortLabel(TileSubmissionType.REQUIRES_INTERACTION));
        assertEquals("Completed", TileStatusStyle.displayText(TileSubmissionType.ACCEPTED));
        assertTrue(TileStatusStyle.isSubmitted(TileSubmissionType.PENDING));
    }

    @Test
    public void notSubmittedAndNullFallBackToDefaults() {
        for (TileSubmissionType status : new TileSubmissionType[]{null, TileSubmissionType.NOT_SUBMITTED}) {
            assertEquals(ColorScheme.DARK_GRAY_COLOR, TileStatusStyle.background(status));
            assertEquals(ColorScheme.BORDER_COLOR, TileStatusStyle.border(status));
            assertEquals(Color.LIGHT_GRAY, TileStatusStyle.accent(status));
            assertEquals("#ffffff", TileStatusStyle.hex(status));
            assertNull(TileStatusStyle.shortLabel(status));
            assertEquals("Not Submitted", TileStatusStyle.displayText(status));
            assertFalse(TileStatusStyle.isSubmitted(status));
        }
    }
}
